insert into public.exams (id, slug, name, description, is_active) values ('a1000000-0000-4000-8000-000000000001', 'plab1', 'PLAB 1', 'PLAB 1 single best answer study bank (PLABoratory).', true) on conflict (slug) do update set name = excluded.name, is_active = true;
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('dc75069a-2731-596f-a1bd-470e39e4a4c7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 34 year old man is brought to the emergency department by ambulance after being found collapsed in a flat with a gas fire running. He was with his partner, who also complains of headache and nausea. He is drowsy but rousable. His heart rate is 110 bpm, BP 118/76 mmHg, RR 22/min and SpO2 is 99% on room air on the pulse oximeter. His skin is pink. A venous blood gas shows a lactate of 4.1 mmol/L. What is the SINGLE most appropriate next step?', 'Pulse oximeters cannot distinguish carboxyhaemoglobin from oxyhaemoglobin, so SpO2 is falsely normal. Clues: several people unwell in the same building, headache, nausea, and a fire or faulty boiler. Give high-flow oxygen (shortens CO half-life) and measure COHb. Hyperbaric oxygen is considered for severe cases (loss of consciousness, pregnancy, neurological signs).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e897a481-b35a-5d22-aa2a-62bc33b5865c', 'dc75069a-2731-596f-a1bd-470e39e4a4c7', 'A', 'Give 100% oxygen via a non-rebreather mask and measure carboxyhaemoglobin on a co-oximetry blood gas', true, 0),
  ('d5f25914-ee58-5ace-ae89-a8dfa729fde0', 'dc75069a-2731-596f-a1bd-470e39e4a4c7', 'B', 'Arrange CT head before any treatment', false, 1),
  ('e5d1d3af-945e-52c3-a364-4bb651ab4b1a', 'dc75069a-2731-596f-a1bd-470e39e4a4c7', 'C', 'Reassure, as oxygen saturation is normal', false, 2),
  ('e85535f0-99a7-59ac-83cb-a5d0ded0ef9e', 'dc75069a-2731-596f-a1bd-470e39e4a4c7', 'D', 'Give IV naloxone', false, 3),
  ('4d2813c5-257f-5f40-bbcb-527ad0b1e233', 'dc75069a-2731-596f-a1bd-470e39e4a4c7', 'E', 'Discharge with advice to ventilate the flat', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('99bbe15b-6908-5724-802a-cc0c7a3fefc8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 19 year old woman is brought in by her friends from a nightclub. She took two tablets of an unknown drug 3 hours ago and has been dancing and drinking large volumes of water. She is now confused and had a seizure in the ambulance. Her temperature is 37.8 °C, HR 115 bpm, BP 140/90 mmHg. Her pupils are dilated. Blood tests show: Na+ 118 mmol/L, K+ 4.0 mmol/L, glucose 6.1 mmol/L. What is the SINGLE most appropriate treatment for her sodium?', 'MDMA causes SIADH and the user drinks large volumes of water, leading to acute severe hyponatraemia. Severe symptoms (seizures, reduced consciousness) need hypertonic saline (e.g. 150 mL of 2.7% over 15-20 minutes), aiming for a rise of about 5 mmol/L initially, then no more than 10 mmol/L in 24 hours. Also watch for hyperthermia and serotonin toxicity.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8e7a7492-c65b-545a-bbe3-6d44498c743d', '99bbe15b-6908-5724-802a-cc0c7a3fefc8', 'A', 'IV 5% dextrose', false, 0),
  ('91889926-a3a2-522c-bb82-74fe55a0cd1f', '99bbe15b-6908-5724-802a-cc0c7a3fefc8', 'B', 'IV 2.7% (or 3%) hypertonic saline bolus, with close sodium monitoring', true, 1),
  ('f483eebd-1b0a-5611-98af-bc916b2ce414', '99bbe15b-6908-5724-802a-cc0c7a3fefc8', 'C', 'Fluid restriction alone', false, 2),
  ('362adc8d-2dca-5454-8232-e9e0b166b850', '99bbe15b-6908-5724-802a-cc0c7a3fefc8', 'D', 'IV 0.9% saline 1 L over 1 hour', false, 3),
  ('776a2f37-4f8f-58a0-a533-73885928832a', '99bbe15b-6908-5724-802a-cc0c7a3fefc8', 'E', 'Oral salt tablets', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ebdbe682-60d2-5a53-8958-a366a0f07198', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 52 year old man presents to the emergency department with severe central chest pain radiating to his back, which started suddenly 1 hour ago while lifting a heavy box at work. He has a history of hypertension and does not take his medication. His HR is 105 bpm. BP is 178/96 mmHg in the right arm and 140/80 mmHg in the left arm. There is an early diastolic murmur at the left sternal edge. ECG shows sinus tachycardia with left ventricular hypertrophy and no ST changes. Troponin is pending. What is the SINGLE most appropriate next step?', 'Features of aortic dissection: sudden tearing pain radiating to the back, BP difference between arms of over 20 mmHg, new aortic regurgitation murmur, and hypertension. Antiplatelets and anticoagulants can be fatal. Type A (ascending) needs emergency surgery; type B is managed medically unless complicated.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d0ef093b-73e0-5ae5-88f1-343e71e0fde9', 'ebdbe682-60d2-5a53-8958-a366a0f07198', 'A', 'Urgent CT aortogram, with IV analgesia and BP control, and avoid antiplatelets and anticoagulants until dissection is excluded', true, 0),
  ('2ac80b7a-160c-5d44-920c-fb1b79d71cde', 'ebdbe682-60d2-5a53-8958-a366a0f07198', 'B', 'Thrombolysis', false, 1),
  ('75cbf834-8e1c-5c54-b9ad-ce32b6a3d1ca', 'ebdbe682-60d2-5a53-8958-a366a0f07198', 'C', 'Give aspirin 300 mg and ticagrelor and arrange angiography', false, 2),
  ('685aeb80-7cee-55ac-b8da-3b56416cda44', 'ebdbe682-60d2-5a53-8958-a366a0f07198', 'D', 'Discharge if troponin negative', false, 3),
  ('8a8bc7c5-06d5-5248-b1bc-307ca245f3cc', 'ebdbe682-60d2-5a53-8958-a366a0f07198', 'E', 'Exercise tolerance test', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('54e49336-1fec-57b7-b941-052a3bf4991e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 72 year old woman presents with a 2-day history of vomiting and abdominal pain. She has a history of atrial fibrillation and heart failure and takes digoxin, furosemide and apixaban. She reports seeing yellow halos around lights. Her HR is 44 bpm and irregular. BP is 102/64 mmHg. ECG shows slow AF with ''reverse tick'' ST depression and frequent ventricular ectopics. Blood tests: K+ 6.1 mmol/L, creatinine 210 micromol/L (baseline 98). What is the SINGLE most appropriate specific treatment?', 'Digoxin toxicity is precipitated by AKI and electrolyte disturbance. Features: nausea, visual changes (xanthopsia), bradyarrhythmias and ventricular arrhythmias. Hyperkalaemia indicates severe toxicity. Digoxin-specific Fab is used for life-threatening arrhythmias, hyperkalaemia over 5 or haemodynamic compromise. Stop digoxin.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c536322d-d44d-5ce3-b1b3-e8e49cfb1660', '54e49336-1fec-57b7-b941-052a3bf4991e', 'A', 'IV amiodarone', false, 0),
  ('3118a716-3201-5132-848a-d165e63388f6', '54e49336-1fec-57b7-b941-052a3bf4991e', 'B', 'IV calcium gluconate first-line for digoxin toxicity', false, 1),
  ('051f24bd-e657-52c2-9757-3b92807208b2', '54e49336-1fec-57b7-b941-052a3bf4991e', 'C', 'Digoxin-specific antibody fragments (DigiFab)', true, 2),
  ('b603c858-dbad-56be-a110-e5483ea9113e', '54e49336-1fec-57b7-b941-052a3bf4991e', 'D', 'IV insulin-dextrose only', false, 3),
  ('66cff935-ee4d-53a2-bbb9-4480dc598d3d', '54e49336-1fec-57b7-b941-052a3bf4991e', 'E', 'Increase furosemide', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2937d3c4-bea4-5c16-91bb-c4ed3e0a68f4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 23 year old man is brought to the emergency department 20 minutes after being stabbed in the left chest at the level of the 4th intercostal space, just lateral to the sternum. He is pale and agitated. HR is 130 bpm, BP 78/60 mmHg. His neck veins are distended. Breath sounds are present and equal on both sides. Heart sounds are muffled. Trachea is central. What is the SINGLE most appropriate immediate management?', 'Beck''s triad (hypotension, raised JVP, muffled heart sounds) after penetrating trauma in the ''cardiac box'' indicates cardiac tamponade. Equal breath sounds and a central trachea make tension pneumothorax less likely. eFAST confirms. Emergency department thoracotomy is preferred for traumatic tamponade with arrest or peri-arrest.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4d94e6c9-3eb6-5b76-82e3-189aff91eb98', '2937d3c4-bea4-5c16-91bb-c4ed3e0a68f4', 'A', 'Intubate and observe', false, 0),
  ('aeab7743-057c-5f62-869d-658a0a7f937d', '2937d3c4-bea4-5c16-91bb-c4ed3e0a68f4', 'B', 'Needle decompression of the left chest', false, 1),
  ('fc2da5dc-379a-58ed-afb8-549fe00cfab0', '2937d3c4-bea4-5c16-91bb-c4ed3e0a68f4', 'C', 'Chest drain on the left', false, 2),
  ('c8019eb1-67c8-54a4-a8e6-bd8845db1221', '2937d3c4-bea4-5c16-91bb-c4ed3e0a68f4', 'D', 'Emergency thoracotomy or pericardiocentesis for cardiac tamponade, with call for cardiothoracic help', true, 3),
  ('f9f79fc9-2ce1-5fbb-b8e1-c8d52b6c562c', '2937d3c4-bea4-5c16-91bb-c4ed3e0a68f4', 'E', 'Large-volume IV crystalloid and CT', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1869733c-e706-5c21-bce6-9f099f76a21b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000023', 'sba', 'A 45 year old woman with a history of depression is brought to the emergency department 6 hours after taking an unknown number of aspirin tablets. She has nausea, ringing in her ears and is breathing fast. Her temperature is 37.9 °C. Arterial blood gas on air: pH 7.38, PaCO2 3.1 kPa, PaO2 13.5 kPa, HCO3- 13 mmol/L, lactate 3.0. Salicylate level is 650 mg/L. Her creatinine is normal. What is the SINGLE most appropriate treatment?', 'Salicylate poisoning causes a mixed respiratory alkalosis and metabolic acidosis, tinnitus, sweating and hyperthermia. Urinary alkalinisation (IV bicarbonate) is used for moderate toxicity. Haemodialysis is indicated for levels over 700 mg/L, or for severe features: CNS effects, AKI, pulmonary oedema or resistant acidosis. Levels near 700 with acidosis warrant discussion for dialysis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('462b812e-dc2a-59ad-be7c-69f0a530b8ce', '1869733c-e706-5c21-bce6-9f099f76a21b', 'A', 'IV sodium bicarbonate only', false, 0),
  ('57c4756e-c4ae-5230-9337-20efde0c6f75', '1869733c-e706-5c21-bce6-9f099f76a21b', 'B', 'N-acetylcysteine', false, 1),
  ('de8485f2-49d3-5097-a2c3-814bcfa67a9c', '1869733c-e706-5c21-bce6-9f099f76a21b', 'C', 'Observe and repeat level in 12 hours', false, 2),
  ('52b99e44-4b41-5bdc-a9be-75fd284a046d', '1869733c-e706-5c21-bce6-9f099f76a21b', 'D', 'Haemodialysis', true, 3),
  ('ce47dec2-4b03-594f-b61a-675d99cb7aca', '1869733c-e706-5c21-bce6-9f099f76a21b', 'E', 'Activated charcoal only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1cb11f6b-dbd4-5c89-ba18-22f0cdb98d27', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 68 year old man presents with breathlessness on exertion and orthopnoea that has worsened over 3 months. He had a myocardial infarction 2 years ago. On examination there are bibasal crackles, a raised JVP and pitting oedema to the knees. NT-proBNP is 3,200 ng/L. Echocardiogram shows an ejection fraction of 30%. He is on ramipril and bisoprolol at maximum tolerated doses, and furosemide. His potassium is 4.6 mmol/L and eGFR is 55. What is the SINGLE most appropriate additional drug to improve prognosis?', 'NICE NG106: HFrEF first-line is ACE inhibitor (or ARB) plus beta-blocker, adding an MRA if symptoms continue, and an SGLT2 inhibitor (dapagliflozin or empagliflozin). Sacubitril-valsartan replaces ACE inhibitors under specialist advice if EF is 35% or less. Verapamil and diltiazem are contraindicated in HFrEF. Monitor potassium and renal function.', null, true, true, jsonb_build_object('source', 'plab1-xlsx-v7', 'guidelines_text', 'NICE NG106')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('118f9622-4155-51f0-83ce-4997357542be', '1cb11f6b-dbd4-5c89-ba18-22f0cdb98d27', 'A', 'Verapamil', false, 0),
  ('22da139d-1efd-5f3f-b2ce-c4950244c29b', '1cb11f6b-dbd4-5c89-ba18-22f0cdb98d27', 'B', 'Digoxin', false, 1),
  ('79a9e618-93d6-5eef-8380-a0e780643a40', '1cb11f6b-dbd4-5c89-ba18-22f0cdb98d27', 'C', 'Spironolactone (mineralocorticoid receptor antagonist), with an SGLT2 inhibitor also recommended', true, 2),
  ('8d99e6cc-e307-5b05-a860-20448a3e0d34', '1cb11f6b-dbd4-5c89-ba18-22f0cdb98d27', 'D', 'Increase furosemide only', false, 3),
  ('447db726-2ba6-5c07-8b92-61c150a5916a', '1cb11f6b-dbd4-5c89-ba18-22f0cdb98d27', 'E', 'Amlodipine', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('96d72100-3e47-5937-94e7-4ec22992f214', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 76 year old woman has had palpitations for 2 days. She has hypertension and type 2 diabetes. ECG shows atrial fibrillation with a ventricular rate of 132 bpm. Her BP is 138/84 mmHg, and she has no chest pain, breathlessness or signs of heart failure. Her creatinine clearance is 55 mL/min. She has no history of bleeding. What is the SINGLE most appropriate management?', 'She is haemodynamically stable with AF over 48 hours, so rate control is first-line. CHA2DS2-VASc: age 75+ (2), female (1), hypertension (1), diabetes (1) = 5. Anticoagulation is recommended with a score of 2 or more (DOAC first-line). Assess bleeding risk with ORBIT. Aspirin is not used for stroke prevention in AF.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7', 'guidelines_text', 'CHA2DS2-VASc')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4dd86d3f-068f-57a9-9b7a-dc69f0db01cb', '96d72100-3e47-5937-94e7-4ec22992f214', 'A', 'Aspirin alone', false, 0),
  ('bdfe7765-f3af-54f3-818c-c0055b683850', '96d72100-3e47-5937-94e7-4ec22992f214', 'B', 'Rate control with a beta-blocker and anticoagulation with a DOAC (CHA2DS2-VASc score 4)', true, 1),
  ('57664e16-38b0-5f26-ab54-20325e8bf153', '96d72100-3e47-5937-94e7-4ec22992f214', 'C', 'Immediate DC cardioversion', false, 2),
  ('4e93cbbd-a161-555b-9b0e-7511e6568cf3', '96d72100-3e47-5937-94e7-4ec22992f214', 'D', 'Amiodarone and no anticoagulation', false, 3),
  ('6d4e8ad7-3463-56a5-aff5-9f9fe990732b', '96d72100-3e47-5937-94e7-4ec22992f214', 'E', 'Warfarin only after 3 months of observation', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b714b3c6-1b72-532b-b28e-25f940a50fe6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 55 year old man presents with central crushing chest pain for 40 minutes, sweating and nausea. He is pale. HR 88 bpm, BP 132/80 mmHg. ECG shows ST elevation of 3 mm in leads II, III and aVF, with ST depression in I and aVL. The nearest primary PCI centre can perform the procedure within 60 minutes. He has received aspirin 300 mg. What is the SINGLE most appropriate next step?', 'Inferior STEMI: primary PCI if within 12 hours of onset and can be delivered within 120 minutes of when fibrinolysis could have been given. Record V4R to look for right ventricular infarction; if present, avoid nitrates and give fluids for hypotension.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f41b89eb-840a-5d41-a99a-45ca6a27a261', 'b714b3c6-1b72-532b-b28e-25f940a50fe6', 'A', 'Thrombolysis with alteplase', false, 0),
  ('2bc435bf-67ee-5d3e-947f-ad7e28b19d79', 'b714b3c6-1b72-532b-b28e-25f940a50fe6', 'B', 'Immediate transfer for primary PCI with a second antiplatelet (e.g. prasugrel or ticagrelor) and right-sided ECG', true, 1),
  ('8a5663fa-7346-5a93-8689-5ca4cb8b194f', 'b714b3c6-1b72-532b-b28e-25f940a50fe6', 'C', 'CT coronary angiogram', false, 2),
  ('bf038af3-7129-5461-ab68-79ca3c5219b1', 'b714b3c6-1b72-532b-b28e-25f940a50fe6', 'D', 'Wait for troponin result', false, 3),
  ('6f9ce94a-767f-527b-b502-29dbf1e50514', 'b714b3c6-1b72-532b-b28e-25f940a50fe6', 'E', 'IV GTN and discharge if pain resolves', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5286c13c-7b52-56e3-9bfe-0a1f418c14c5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000001', 'sba', 'A 30 year old woman presents with fever, night sweats and weight loss for 6 weeks. She injects heroin. On examination there are splinter haemorrhages, a pansystolic murmur at the left lower sternal edge that increases on inspiration, and a pulsatile liver. CXR shows multiple round opacities in both lungs. Three sets of blood cultures are taken. What is the SINGLE most likely diagnosis?', 'Right-sided endocarditis occurs in people who inject drugs. A murmur of tricuspid regurgitation increases with inspiration (Carvallo''s sign). Septic emboli cause multiple lung nodules. Use modified Duke criteria. Treat with IV antibiotics (flucloxacillin for MSSA) for weeks. Offer BBV testing.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f0d39683-ba6f-56c8-9a55-2df5a0c26a38', '5286c13c-7b52-56e3-9bfe-0a1f418c14c5', 'A', 'Pulmonary TB', false, 0),
  ('8d838b9b-2409-5d10-aa3b-78a6217ecb77', '5286c13c-7b52-56e3-9bfe-0a1f418c14c5', 'B', 'Mitral regurgitation from rheumatic fever', false, 1),
  ('864e8f92-c2ae-5436-88f7-e87918298afd', '5286c13c-7b52-56e3-9bfe-0a1f418c14c5', 'C', 'Tricuspid valve infective endocarditis with septic pulmonary emboli (likely S. aureus)', true, 2),
  ('d04ddf5c-9160-5bec-90d3-ce17ba7e683a', '5286c13c-7b52-56e3-9bfe-0a1f418c14c5', 'D', 'Pneumocystis pneumonia', false, 3),
  ('6e913189-94e0-5264-adf4-6121fb5adc58', '5286c13c-7b52-56e3-9bfe-0a1f418c14c5', 'E', 'Lung abscess from aspiration', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c286a598-7160-5c1e-9708-db0d63a6f664', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 3 week old boy, born at term, is brought in by his parents with projectile vomiting after every feed for 4 days. The vomit is not green. He seems hungry immediately after vomiting. He has had fewer wet nappies. On examination he is mildly dehydrated, and a small olive-shaped mass is felt in the right upper abdomen during a test feed. Capillary blood gas: pH 7.52, HCO3- 34 mmol/L, Cl- 88 mmol/L, K+ 3.0 mmol/L. What is the SINGLE most appropriate next step?', 'Pyloric stenosis: projectile non-bilious vomiting at 2-8 weeks, typically in firstborn boys. Hypochloraemic hypokalaemic metabolic alkalosis. Ultrasound confirms. Correct dehydration and electrolytes first (alkalosis increases risk of post-operative apnoea), then Ramstedt''s pyloromyotomy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2faee3f8-7273-5882-8205-9d2d0fbd5561', 'c286a598-7160-5c1e-9708-db0d63a6f664', 'A', 'Correct fluid and electrolyte disturbance with IV fluids before pyloromyotomy', true, 0),
  ('4745c381-8cc8-5e36-85bf-1771015e8172', 'c286a598-7160-5c1e-9708-db0d63a6f664', 'B', 'Start an anti-reflux medicine and discharge', false, 1),
  ('fe32b55a-2e55-5178-a9fe-dab67205e638', 'c286a598-7160-5c1e-9708-db0d63a6f664', 'C', 'Upper GI contrast study and observe', false, 2),
  ('abd8869f-110f-5999-8e9d-06f6c5c4302d', 'c286a598-7160-5c1e-9708-db0d63a6f664', 'D', 'Immediate surgery before correcting the bloods', false, 3),
  ('29b1f847-7b98-5ffd-8ef8-70580048eeeb', 'c286a598-7160-5c1e-9708-db0d63a6f664', 'E', 'Change to a hydrolysed formula', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('81c17b08-f8b1-53c3-8c2f-62385abd4c3d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 9 month old girl is brought to the emergency department with episodes of inconsolable crying lasting a few minutes, when she draws her legs up. Between episodes she is pale and lethargic. She has vomited twice and her last nappy contained a mix of blood and mucus. She had a cold last week. Her temperature is 37.6 °C, HR 165 bpm. There is a sausage-shaped mass in the right upper abdomen. What is the SINGLE most appropriate management?', 'Intussusception occurs mostly at 3 months to 2 years, often after a viral illness (enlarged Peyer''s patches). Ultrasound shows a ''target sign''. Air enema reduction is successful in most cases. Surgery if perforation, peritonitis or failed reduction.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f4faa811-a11d-570a-9c52-2ec8a9476655', '81c17b08-f8b1-53c3-8c2f-62385abd4c3d', 'A', 'IV fluid resuscitation and ultrasound, followed by air enema reduction if no peritonitis', true, 0),
  ('acb7e0b5-9803-5c5d-b680-823a4a7e9abe', '81c17b08-f8b1-53c3-8c2f-62385abd4c3d', 'B', 'Laparotomy immediately in all cases', false, 1),
  ('da0bf807-e443-5bbc-bf93-96c3a9fe36f7', '81c17b08-f8b1-53c3-8c2f-62385abd4c3d', 'C', 'Stool culture and antibiotics', false, 2),
  ('19438f92-5fc8-5194-a979-8d7fc5c0f074', '81c17b08-f8b1-53c3-8c2f-62385abd4c3d', 'D', 'Oral rehydration and review in 24 hours', false, 3),
  ('eb24c8a5-edfa-52d6-a2b0-77c7fd2fc3da', '81c17b08-f8b1-53c3-8c2f-62385abd4c3d', 'E', 'Barium swallow', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f62d9c11-8d48-5f61-a81a-8f41fea8f3ee', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 4 year old boy is brought by his mother with puffy eyes in the morning for 1 week, which have spread to his legs and scrotum. He is otherwise well. BP is 96/60 mmHg. Urine dipstick shows protein 4+ and no blood. Urine protein:creatinine ratio is 600 mg/mmol. Serum albumin is 18 g/L. Creatinine is normal and complement levels are normal. What is the SINGLE most appropriate treatment?', 'Nephrotic syndrome in children aged 1-10 is usually minimal change disease, which is steroid-sensitive. Biopsy is reserved for atypical features (age under 1 or over 12, haematuria, hypertension, low complement, renal impairment, steroid resistance). Complications: infection (pneumococcal peritonitis), thrombosis, hypovolaemia. Give penicillin prophylaxis in some units.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a7716e56-69cd-5dcb-b78a-2651510550cb', 'f62d9c11-8d48-5f61-a81a-8f41fea8f3ee', 'A', 'Ciclosporin first-line', false, 0),
  ('0aa4a974-0745-56e7-9af1-cc7e22ca9f94', 'f62d9c11-8d48-5f61-a81a-8f41fea8f3ee', 'B', 'Antibiotics', false, 1),
  ('65c5d41b-90c5-520a-b1c8-f95a31394e1b', 'f62d9c11-8d48-5f61-a81a-8f41fea8f3ee', 'C', 'Renal biopsy before any treatment', false, 2),
  ('e6f5a107-c35a-550a-b242-e7c8532003a2', 'f62d9c11-8d48-5f61-a81a-8f41fea8f3ee', 'D', 'Oral prednisolone (60 mg/m2/day) for 4 weeks, then tapering', true, 3),
  ('1f33b7b3-9959-573d-877f-ca7d95cb289f', 'f62d9c11-8d48-5f61-a81a-8f41fea8f3ee', 'E', 'IV albumin and furosemide only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('23421dc6-b5d0-5537-b1cb-45e92317d193', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 7 year old girl is brought to the GP with a 2-week history of a limp and a rash. Her mother says she had a sore throat 2 weeks ago. On examination there is a purple raised rash on the backs of her legs and buttocks, which does not blanch. Her knees and ankles are swollen and painful. She has had abdominal pain. Her BP is 102/66 mmHg. Platelet count is normal. Urine dipstick shows blood 2+ and protein 1+. What is the SINGLE most appropriate management?', 'IgA vasculitis (Henoch-Schönlein purpura) causes palpable purpura on the legs and buttocks with a normal platelet count, arthritis, abdominal pain and nephritis. Most resolve. Intussusception is a complication. Monitor BP and urine; refer if significant proteinuria, hypertension or renal impairment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4b11c89a-c6d1-5583-a5e1-a4bc03778a78', '23421dc6-b5d0-5537-b1cb-45e92317d193', 'A', 'Bone marrow aspirate', false, 0),
  ('e489cf77-49da-5254-8b63-500cdfe6581e', '23421dc6-b5d0-5537-b1cb-45e92317d193', 'B', 'IV antibiotics for meningococcal sepsis', false, 1),
  ('4da25046-4116-5433-9cdf-9a4cf58edb1d', '23421dc6-b5d0-5537-b1cb-45e92317d193', 'C', 'Supportive care with analgesia, and monitoring of BP and urine for renal involvement for 6-12 months', true, 2),
  ('9825d089-06b1-5cdd-9aae-72466dc0b91b', '23421dc6-b5d0-5537-b1cb-45e92317d193', 'D', 'Platelet transfusion', false, 3),
  ('f31a1649-7398-5242-ba26-f49edd2c37e4', '23421dc6-b5d0-5537-b1cb-45e92317d193', 'E', 'Urgent splenectomy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c20a8966-9c7e-5280-b926-a44058ba23ba', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 2 year old boy is brought to the emergency department with a 6-day history of high fever unresponsive to paracetamol. He is very irritable. On examination he has bilateral non-purulent red eyes, red cracked lips, a ''strawberry'' tongue, swelling of his hands and feet, a widespread polymorphous rash and a single enlarged lymph node in his neck measuring 2 cm. CRP is 140 mg/L. Platelets are 520 x 10^9/L. What is the SINGLE most appropriate treatment?', 'Kawasaki disease: fever for 5 days or more with 4 of the 5 features (conjunctivitis, mucosal changes, extremity changes, rash, cervical lymphadenopathy). The main complication is coronary artery aneurysm. Treatment: IVIG within 10 days and aspirin (an exception to avoiding aspirin in children). High-risk cases may receive steroids.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1d9633d3-07dc-50e7-8852-4439d782bbf0', 'c20a8966-9c7e-5280-b926-a44058ba23ba', 'A', 'Oral penicillin V', false, 0),
  ('5e1c9f61-51ab-5c1f-8709-267b8cf30045', 'c20a8966-9c7e-5280-b926-a44058ba23ba', 'B', 'No treatment, as it is viral', false, 1),
  ('3de51de9-5dd0-52a7-bdf7-bc6ba718d560', 'c20a8966-9c7e-5280-b926-a44058ba23ba', 'C', 'IV immunoglobulin and aspirin, with echocardiography', true, 2),
  ('00a8e265-5a5e-57bc-9245-eff69553a18d', 'c20a8966-9c7e-5280-b926-a44058ba23ba', 'D', 'IV ceftriaxone only', false, 3),
  ('8854f576-93aa-5b61-8204-5a8c0bf4fc6b', 'c20a8966-9c7e-5280-b926-a44058ba23ba', 'E', 'Oral prednisolone alone and discharge', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('504b4734-8ace-5621-adb5-2fd9ef4880fe', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 32 year old woman, gravida 2 para 1, at 36 weeks of pregnancy attends the maternity unit with headache and flashing lights. She feels unwell and has pain under her right ribs. BP is 168/112 mmHg on repeated readings. Urine shows protein 3+. Blood tests: Hb 98 g/L, platelets 72 x 10^9/L, ALT 210 U/L, LDH raised. Blood film shows fragmented red cells. What is the SINGLE most likely diagnosis?', 'HELLP: haemolysis, elevated liver enzymes, low platelets. Management: control BP (labetalol, nifedipine or IV hydralazine), IV magnesium sulfate to prevent seizures, steroids if preterm, and delivery after stabilisation. Acute fatty liver causes hypoglycaemia and coagulopathy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('b70d2ede-d189-5582-bcab-c47c445e822e', '504b4734-8ace-5621-adb5-2fd9ef4880fe', 'A', 'TTP', false, 0),
  ('b3740ded-3725-530f-ba30-9cfec65ccdcf', '504b4734-8ace-5621-adb5-2fd9ef4880fe', 'B', 'Gallstones', false, 1),
  ('f45a9105-c284-58f7-985e-538edbebca52', '504b4734-8ace-5621-adb5-2fd9ef4880fe', 'C', 'Obstetric cholestasis', false, 2),
  ('0ddc30fc-f3b2-5dea-9551-04dc1f0e0196', '504b4734-8ace-5621-adb5-2fd9ef4880fe', 'D', 'Acute fatty liver of pregnancy', false, 3),
  ('54f36d20-02c5-51c8-a193-c5e561946faa', '504b4734-8ace-5621-adb5-2fd9ef4880fe', 'E', 'HELLP syndrome (with severe pre-eclampsia)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('adddea3d-ad5e-5c9a-b956-e936d45534cc', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 27 year old woman at 39 weeks of pregnancy has been in labour for 14 hours. She had an epidural. She delivers a 4.3 kg baby after a prolonged second stage with a forceps delivery. Ten minutes after the placenta is delivered she has heavy vaginal bleeding of 1,200 mL. The placenta appears complete. On examination the uterus is soft and boggy and lies above the umbilicus. HR 118 bpm, BP 98/60 mmHg. IV access has been obtained and she has been given oxytocin. What is the SINGLE most appropriate next step?', 'PPH causes (4Ts): tone (most common), trauma, tissue, thrombin. Uterine atony risk factors: prolonged labour, macrosomia, instrumental delivery, multiple pregnancy. Steps: rub up the fundus, empty the bladder, uterotonics, tranexamic acid, then balloon tamponade, B-Lynch suture, interventional radiology, hysterectomy. Ergometrine is avoided in hypertension.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f30662ff-25d5-57ee-b615-b5dc040cd8c8', 'adddea3d-ad5e-5c9a-b956-e936d45534cc', 'A', 'Give IV antibiotics only', false, 0),
  ('e6c3d692-4c54-50f1-bbda-e9d5d9a2e8b7', 'adddea3d-ad5e-5c9a-b956-e936d45534cc', 'B', 'Wait and observe for 30 minutes', false, 1),
  ('04da656b-1db3-5409-9977-ee039e0f8f61', 'adddea3d-ad5e-5c9a-b956-e936d45534cc', 'C', 'Immediate hysterectomy first', false, 2),
  ('9e6127c9-179d-5633-98aa-839a1a3cd229', 'adddea3d-ad5e-5c9a-b956-e936d45534cc', 'D', 'Discharge to the postnatal ward', false, 3),
  ('a2e98df1-fe38-570c-96f0-e897eccf1f48', 'adddea3d-ad5e-5c9a-b956-e936d45534cc', 'E', 'Bimanual uterine compression and further uterotonics (ergometrine, carboprost, misoprostol), with tranexamic acid and major haemorrhage protocol', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ccd080cb-1232-5be5-bcd3-66a7df335f50', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 29 year old woman presents to the early pregnancy unit with left iliac fossa pain and light vaginal bleeding. Her last menstrual period was 7 weeks ago. She had a chlamydia infection 3 years ago. She is haemodynamically stable. Transvaginal ultrasound shows an empty uterus and a 25 mm adnexal mass with no fetal heartbeat and no free fluid. Serum hCG is 1,800 IU/L. She has no significant pain at the moment. What is the SINGLE most appropriate management?', 'NICE NG126: methotrexate is first-line if no significant pain, unruptured ectopic under 35 mm with no heartbeat, hCG under 1,500 IU/L, and can return for follow-up. With hCG 1,500-5,000, methotrexate or surgery can be offered. Surgery (salpingectomy) for heartbeat, hCG over 5,000, significant pain or rupture. Avoid pregnancy for 3 months after methotrexate.', null, true, true, jsonb_build_object('source', 'plab1-xlsx-v7', 'guidelines_text', 'NICE NG126')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d1c9b1f3-40af-51ab-8d30-342a518b2508', 'ccd080cb-1232-5be5-bcd3-66a7df335f50', 'A', 'Laparoscopic salpingectomy in all', false, 0),
  ('c1e0abaf-165c-5686-8fef-27a2730952eb', 'ccd080cb-1232-5be5-bcd3-66a7df335f50', 'B', 'Dilatation and curettage', false, 1),
  ('b16fc2d2-97d6-5432-9f78-354e4c7f31ac', 'ccd080cb-1232-5be5-bcd3-66a7df335f50', 'C', 'Expectant management with no follow-up', false, 2),
  ('0a3e1d17-21e3-5279-ba47-3db28f1058aa', 'ccd080cb-1232-5be5-bcd3-66a7df335f50', 'D', 'Medical management with methotrexate (IM), with hCG follow-up', true, 3),
  ('24de3405-4ddc-5efb-925f-4664079438b1', 'ccd080cb-1232-5be5-bcd3-66a7df335f50', 'E', 'Repeat scan in 4 weeks', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('fcc8ad7e-bded-5213-b6c0-34591f1e1754', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 34 year old woman presents with a 6-month history of irregular, heavy periods, increased hair on her chin and acne. She is trying to conceive. Her BMI is 33. Blood tests show raised testosterone, an LH:FSH ratio of 3:1 and normal prolactin and TSH. Ultrasound shows 22 follicles in each ovary. She has a regular partner whose semen analysis is normal. What is the SINGLE most appropriate first-line treatment to help her conceive?', 'PCOS (Rotterdam criteria: 2 of oligo-anovulation, hyperandrogenism and polycystic ovaries). Weight loss improves ovulation. Letrozole is now first-line for ovulation induction (higher live birth rate than clomifene). The pill and spironolactone are not used when trying to conceive (spironolactone is teratogenic).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8fff3ae4-8904-5186-b80d-7ddf169b55a9', 'fcc8ad7e-bded-5213-b6c0-34591f1e1754', 'A', 'Clomifene plus metformin for all at once', false, 0),
  ('9822cd28-24a7-5cb8-9ceb-b118a2577eef', 'fcc8ad7e-bded-5213-b6c0-34591f1e1754', 'B', 'Immediate IVF', false, 1),
  ('630f88ea-e9d2-5259-8954-bb1fb26ac649', 'fcc8ad7e-bded-5213-b6c0-34591f1e1754', 'C', 'Combined oral contraceptive pill', false, 2),
  ('e01cc2e9-fbf8-56fb-b231-b3cbd1a589a1', 'fcc8ad7e-bded-5213-b6c0-34591f1e1754', 'D', 'Spironolactone', false, 3),
  ('32df6513-2b24-54ce-8043-c18a93952be2', 'fcc8ad7e-bded-5213-b6c0-34591f1e1754', 'E', 'Weight loss and letrozole for ovulation induction', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0162acb3-be78-57a3-b91c-9e850f50f949', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000008', 'sba', 'A 61 year old woman presents with postmenopausal bleeding for 3 weeks. Her periods stopped 9 years ago. She has type 2 diabetes, a BMI of 38 and has never had children. She took tamoxifen for 5 years after breast cancer. Speculum examination shows a normal cervix. Transvaginal ultrasound shows an endometrial thickness of 12 mm. What is the SINGLE most appropriate next step?', 'Endometrial cancer risk factors: obesity, diabetes, nulliparity, late menopause, unopposed oestrogen, tamoxifen, PCOS and Lynch syndrome. Postmenopausal bleeding needs urgent referral. Endometrial thickness over 4 mm needs biopsy. Treatment: total hysterectomy with bilateral salpingo-oophorectomy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1c9e8be4-c248-5f83-8dd3-cc251df82c54', '0162acb3-be78-57a3-b91c-9e850f50f949', 'A', 'Cervical smear only', false, 0),
  ('a31f8f18-0c3c-5392-9ec3-817713f85d08', '0162acb3-be78-57a3-b91c-9e850f50f949', 'B', 'Hysteroscopy and endometrial biopsy (two-week-wait pathway)', true, 1),
  ('8dd18617-0c69-5352-afe5-c6f6e4ea88e7', '0162acb3-be78-57a3-b91c-9e850f50f949', 'C', 'Start HRT', false, 2),
  ('d74608c7-a010-5a75-869e-3a9f5283d56e', '0162acb3-be78-57a3-b91c-9e850f50f949', 'D', 'Reassure; it is atrophic vaginitis', false, 3),
  ('fea9e6d9-6b05-508e-8cb4-c8b5baf203f5', '0162acb3-be78-57a3-b91c-9e850f50f949', 'E', 'Repeat ultrasound in 6 months', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('fef893b9-eaf0-54f4-a169-fbb4a7163fac', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 67 year old man is brought to the emergency department after his wife noticed he had slurred speech and weakness of his right arm and face when he woke up this morning. He was last seen well at 11 pm the night before, 9 hours ago. He takes amlodipine. He is alert. BP is 172/94 mmHg, glucose is 6.2 mmol/L. NIHSS score is 9. Non-contrast CT shows no haemorrhage. CT angiogram shows an occlusion of the left middle cerebral artery (M1). CT perfusion shows a small infarct core with a large area of salvageable brain. What is the SINGLE most appropriate management?', 'Wake-up strokes: last known well time is used. NICE NG128: thrombectomy is offered up to 24 hours after last known well for anterior circulation large vessel occlusion if imaging shows salvageable brain. Thrombolysis can be considered with perfusion or MRI evidence of salvageable tissue within 4.5 hours of symptom onset or of sleep midpoint.', null, true, true, jsonb_build_object('source', 'plab1-xlsx-v7', 'guidelines_text', 'NICE NG128')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6d442027-2e43-5921-84cd-2eb761b2c123', 'fef893b9-eaf0-54f4-a169-fbb4a7163fac', 'A', 'Aspirin 300 mg only', false, 0),
  ('16232dc8-13a9-57e3-a77c-cd50b0e510ba', 'fef893b9-eaf0-54f4-a169-fbb4a7163fac', 'B', 'Lower BP to 120/80 urgently', false, 1),
  ('eb07635d-9268-50df-83c0-1560e7e60403', 'fef893b9-eaf0-54f4-a169-fbb4a7163fac', 'C', 'Mechanical thrombectomy (with or without thrombolysis per imaging criteria)', true, 2),
  ('3201ed7e-197a-59c0-8172-d4b30f36ab9c', 'fef893b9-eaf0-54f4-a169-fbb4a7163fac', 'D', 'Carotid endarterectomy', false, 3),
  ('cfad64f7-e7ef-54bc-a85c-bb83f232ac5c', 'fef893b9-eaf0-54f4-a169-fbb4a7163fac', 'E', 'Heparin infusion', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('724e47fd-bdec-59a9-8175-7a67f6399781', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 28 year old woman has had pain behind her right eye on moving it and blurred vision for 5 days. Colours look ''washed out'' in that eye. Two years ago she had numbness in her legs that lasted 3 weeks and resolved. Visual acuity in the right eye is 6/36. There is a right relative afferent pupillary defect. Fundoscopy is normal. MRI brain shows multiple periventricular white matter lesions, some enhancing. What is the SINGLE most likely diagnosis?', 'Optic neuritis causes painful eye movement, reduced acuity and colour vision, and RAPD. ''The patient sees nothing and the doctor sees nothing'' (retrobulbar). Lesions disseminated in time and space confirm MS (McDonald criteria). High-dose steroids speed recovery. Disease-modifying therapy reduces relapses.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2cc76703-6381-5128-b415-62e22c4c4a36', '724e47fd-bdec-59a9-8175-7a67f6399781', 'A', 'Relapsing-remitting multiple sclerosis presenting with optic neuritis', true, 0),
  ('605a56be-0272-5158-b0f6-04b1f202a247', '724e47fd-bdec-59a9-8175-7a67f6399781', 'B', 'Idiopathic intracranial hypertension', false, 1),
  ('acfc2aa3-d256-52a8-b341-810894242488', '724e47fd-bdec-59a9-8175-7a67f6399781', 'C', 'Ischaemic optic neuropathy', false, 2),
  ('c476a620-813f-50a4-bdf3-8c13dad90818', '724e47fd-bdec-59a9-8175-7a67f6399781', 'D', 'Neuromyelitis optica only', false, 3),
  ('4a417246-3d77-5d5f-b6d4-dcf2ada69238', '724e47fd-bdec-59a9-8175-7a67f6399781', 'E', 'Giant cell arteritis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('67c398be-14f3-57f2-b159-e0ace583f171', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 74 year old man has had a progressive tremor of his right hand for a year. His wife says he has become slower and his handwriting has become smaller. On examination there is a 4-6 Hz pill-rolling tremor at rest that improves with movement, cogwheel rigidity in the right arm and reduced arm swing on the right when walking. He has also had vivid dreams, acting them out in his sleep, for several years. What is the SINGLE most likely diagnosis?', 'Parkinson''s disease: asymmetrical bradykinesia with rest tremor and/or rigidity. REM sleep behaviour disorder, anosmia and constipation often precede motor features. Treatment: levodopa (with a decarboxylase inhibitor), dopamine agonists or MAO-B inhibitors. Never stop levodopa abruptly (risk of neuroleptic malignant-like syndrome).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('92251e18-a4d1-5f71-825b-6f32e106742d', '67c398be-14f3-57f2-b159-e0ace583f171', 'A', 'Multiple system atrophy', false, 0),
  ('28148b9b-b7f3-512c-bfe3-adca45b06039', '67c398be-14f3-57f2-b159-e0ace583f171', 'B', 'Essential tremor', false, 1),
  ('7747b026-3303-5f7a-a316-ca65c609220b', '67c398be-14f3-57f2-b159-e0ace583f171', 'C', 'Progressive supranuclear palsy', false, 2),
  ('6c21b9b5-0609-503a-950d-8e6a603807df', '67c398be-14f3-57f2-b159-e0ace583f171', 'D', 'Drug-induced parkinsonism', false, 3),
  ('9ba99e19-0e50-56a8-a52b-c65ae46c4227', '67c398be-14f3-57f2-b159-e0ace583f171', 'E', 'Idiopathic Parkinson''s disease', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5fe974a1-6efe-5d57-8e73-3501825d922e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 38 year old woman presents with a sudden severe headache that came on while she was at the gym, reaching maximum intensity within a minute. She vomited and has neck stiffness. GCS is 15. There are no focal neurological signs. CT head performed 8 hours after onset is normal. What is the SINGLE most appropriate next step?', 'Thunderclap headache: suspect subarachnoid haemorrhage. CT within 6 hours of onset is highly sensitive; after 6 hours, a normal CT needs LP at least 12 hours after onset for xanthochromia. If confirmed, CT angiography to find an aneurysm, nimodipine to prevent vasospasm, and coiling or clipping.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e07b51bf-606a-5699-9498-5c54e8e10ffd', '5fe974a1-6efe-5d57-8e73-3501825d922e', 'A', 'Lumbar puncture at least 12 hours after headache onset, looking for xanthochromia', true, 0),
  ('e1d19b91-e0cb-5006-8bc3-c83078a0ebaa', '5fe974a1-6efe-5d57-8e73-3501825d922e', 'B', 'Repeat CT in 1 week', false, 1),
  ('84e16836-0a9e-5fb6-9097-6d3af4b59c03', '5fe974a1-6efe-5d57-8e73-3501825d922e', 'C', 'MRI in 6 weeks', false, 2),
  ('b9ccfd75-ddef-52e6-b43f-a8d968cc3bbf', '5fe974a1-6efe-5d57-8e73-3501825d922e', 'D', 'Discharge with analgesia', false, 3),
  ('f54d951f-ecc3-5e1e-90b4-ae620eaea8f5', '5fe974a1-6efe-5d57-8e73-3501825d922e', 'E', 'Start triptan', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('df5e6764-8caa-582b-b913-36f0be1668e3', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000006', 'sba', 'A 25 year old woman with known epilepsy is brought to the emergency department in a tonic-clonic seizure that started 8 minutes ago. Paramedics gave buccal midazolam 10 mg 5 minutes ago without effect. She has IV access. Her capillary glucose is 5.8 mmol/L. Her airway is maintained with a nasopharyngeal airway and she is receiving oxygen. What is the SINGLE most appropriate next drug?', 'Status epilepticus: seizure over 5 minutes. Give up to two doses of benzodiazepine (including pre-hospital dose). Then second-line: IV levetiracetam, phenytoin or sodium valproate. If seizures continue, rapid sequence induction and anaesthesia (ICU). Check glucose and give thiamine if alcohol misuse is suspected.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bc88d9e8-1a95-53cf-91c5-341d790a0761', 'df5e6764-8caa-582b-b913-36f0be1668e3', 'A', 'IV thiopental', false, 0),
  ('d64c1d6e-4eb5-58f7-b463-d7f9bbc27492', 'df5e6764-8caa-582b-b913-36f0be1668e3', 'B', 'IV lorazepam 4 mg', true, 1),
  ('7f71a5f5-55c5-5991-9d8d-9b7d97bbe38d', 'df5e6764-8caa-582b-b913-36f0be1668e3', 'C', 'Oral levetiracetam', false, 2),
  ('b1b24a6e-e7b5-50ca-aef1-7b0deb48044b', 'df5e6764-8caa-582b-b913-36f0be1668e3', 'D', 'IV phenytoin immediately without a benzodiazepine', false, 3),
  ('789058cd-64c3-52c5-a2c9-446fb8fa395a', 'df5e6764-8caa-582b-b913-36f0be1668e3', 'E', 'Second dose of buccal midazolam', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('68d1f8c3-6aed-5250-9570-b40ba4a1df60', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 24 year old woman with asthma presents with worsening breathlessness over 2 days after a cold. She has been using her salbutamol inhaler every hour. She cannot complete sentences. RR is 30/min, HR 125 bpm, SpO2 93% on air. Peak flow is 38% of her best. Arterial blood gas on air: PaO2 9.8 kPa, PaCO2 5.6 kPa, pH 7.38. She is tiring. What does her blood gas indicate?', 'A normal or rising PaCO2 in acute asthma is a sign of exhaustion. Life-threatening features: PEF under 33%, SpO2 under 92%, PaO2 under 8, normal PaCO2, silent chest, cyanosis, exhaustion, arrhythmia, hypotension. Treatment: oxygen, back-to-back nebulised salbutamol and ipratropium, steroids, IV magnesium, and ICU review.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d4d656e1-14f2-5806-a81b-0a8f058dbaaf', '68d1f8c3-6aed-5250-9570-b40ba4a1df60', 'A', 'Mild asthma', false, 0),
  ('4303c754-6258-5e3a-b736-95fe7e77c7da', '68d1f8c3-6aed-5250-9570-b40ba4a1df60', 'B', 'Panic attack', false, 1),
  ('e81ed0da-d27f-53f1-b25a-9bcd497be07e', '68d1f8c3-6aed-5250-9570-b40ba4a1df60', 'C', 'Hyperventilation syndrome', false, 2),
  ('13e562a0-0105-5ff5-81a8-a9ee87126890', '68d1f8c3-6aed-5250-9570-b40ba4a1df60', 'D', 'Moderate asthma; discharge with steroids', false, 3),
  ('00798fc0-ff9e-5e2e-9155-707e4e0fa023', '68d1f8c3-6aed-5250-9570-b40ba4a1df60', 'E', 'Life-threatening asthma (normal PaCO2 indicates tiring); urgent senior and ICU review', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('00c18b31-e38f-5b65-b6cc-4acb846264d6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 66 year old man with COPD presents with increased breathlessness and green sputum for 3 days. He is drowsy. RR is 28/min. SpO2 is 84% on air. ABG on 28% oxygen via Venturi mask: pH 7.28, PaCO2 8.9 kPa, PaO2 7.6 kPa, HCO3- 32 mmol/L. He has received nebulised salbutamol and ipratropium, prednisolone and antibiotics. One hour later, his repeat ABG shows pH 7.27, PaCO2 9.1 kPa. What is the SINGLE most appropriate next step?', 'Acute hypercapnic respiratory failure with pH under 7.35 and PaCO2 over 6.5 kPa persisting despite optimal medical therapy is an indication for NIV. Target SpO2 88-92%. Agree a ceiling of treatment (whether intubation is appropriate).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5f15ad4b-d00d-5293-addf-306a15e0b029', '00c18b31-e38f-5b65-b6cc-4acb846264d6', 'A', 'Increase oxygen to 15 L via non-rebreather', false, 0),
  ('b003bc25-5b92-5f2d-8739-20ff7bcaf67e', '00c18b31-e38f-5b65-b6cc-4acb846264d6', 'B', 'Discharge with home oxygen', false, 1),
  ('2f31809e-9b7d-59af-88b8-3d0c2c718dfa', '00c18b31-e38f-5b65-b6cc-4acb846264d6', 'C', 'CPAP', false, 2),
  ('946e6c17-eecc-533c-8354-26be9d21d627', '00c18b31-e38f-5b65-b6cc-4acb846264d6', 'D', 'IV aminophylline only', false, 3),
  ('d20642d2-a696-58cf-be55-1d1083d398c8', '00c18b31-e38f-5b65-b6cc-4acb846264d6', 'E', 'Non-invasive ventilation (BiPAP)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5b8b363f-7d78-5d89-9f85-487f1644f316', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 58 year old woman presents with 4 months of a dry cough and worsening breathlessness. She has no history of smoking. On examination there are fine ''velcro-like'' end-inspiratory crackles at both lung bases and finger clubbing. Spirometry shows FEV1/FVC ratio of 85% with reduced FVC. Transfer factor (DLCO) is reduced. High-resolution CT shows subpleural, basal reticulation with honeycombing. Autoimmune screen is negative. What is the SINGLE most likely diagnosis?', 'IPF: restrictive pattern, reduced gas transfer, usual interstitial pneumonia pattern on HRCT. Antifibrotic drugs (pirfenidone or nintedanib) slow decline (NICE criteria based on FVC). Pulmonary rehabilitation, oxygen, and transplant for selected patients. Poor prognosis (median survival 3-5 years).', null, true, true, jsonb_build_object('source', 'plab1-xlsx-v7', 'guidelines_text', 'NICE')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('8e65e72a-aba4-5087-9209-9472c0985dd7', '5b8b363f-7d78-5d89-9f85-487f1644f316', 'A', 'Sarcoidosis', false, 0),
  ('0c2b6d33-0702-5d3f-8002-444d8a04d6e6', '5b8b363f-7d78-5d89-9f85-487f1644f316', 'B', 'Bronchiectasis', false, 1),
  ('332762e3-9bb2-59db-8e29-0db0c33a8678', '5b8b363f-7d78-5d89-9f85-487f1644f316', 'C', 'COPD', false, 2),
  ('889911d0-16e8-5d31-a468-ebdaacd8ee5c', '5b8b363f-7d78-5d89-9f85-487f1644f316', 'D', 'Idiopathic pulmonary fibrosis', true, 3),
  ('cc1a8855-4a0a-55fc-9b62-a4656811e18d', '5b8b363f-7d78-5d89-9f85-487f1644f316', 'E', 'Hypersensitivity pneumonitis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b26e742e-eb0b-5dcb-834d-00517120550a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 52 year old man is admitted with a fever, productive cough and right-sided pleuritic chest pain for 4 days. He is confused (AMTS 7/10). RR is 32/min, BP 88/50 mmHg, urea 9.2 mmol/L. CXR shows right lower lobe consolidation. What is his CURB-65 score and appropriate management?', 'CURB-65: Confusion, Urea over 7, RR 30 or more, BP systolic under 90 or diastolic 60 or less, age 65 or more. He scores 4 (C, U, R, B). Score 3-5 is high severity: IV co-amoxiclav with clarithromycin (local policy), and consider ICU.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7', 'guidelines_text', 'CURB-65')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('49393193-7174-5d81-8e03-bf090286e462', 'b26e742e-eb0b-5dcb-834d-00517120550a', 'A', 'CURB-65 of 4; severe pneumonia needing hospital admission, IV antibiotics and assessment for critical care', true, 0),
  ('4f16d89c-0f19-5c2d-999c-4b73a38038b3', 'b26e742e-eb0b-5dcb-834d-00517120550a', 'B', 'CURB-65 of 1; oral amoxicillin at home', false, 1),
  ('a5c7fa57-5bb8-5a4e-bb4e-1e1b786547ca', 'b26e742e-eb0b-5dcb-834d-00517120550a', 'C', 'CURB-65 of 2; short admission with oral antibiotics', false, 2),
  ('61274dda-5270-5c6c-afa9-5bfb6e2f676e', 'b26e742e-eb0b-5dcb-834d-00517120550a', 'D', 'CURB-65 of 0; no antibiotics', false, 3),
  ('e9b31a57-4601-545f-aad1-d90eb90941a2', 'b26e742e-eb0b-5dcb-834d-00517120550a', 'E', 'CURB-65 of 5; palliation only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('74e5b747-968a-5706-97c6-e4a1288d19ae', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000002', 'sba', 'A 45 year old woman presents with right-sided pleuritic chest pain and breathlessness for 1 day. She had a long-haul flight 5 days ago and takes the combined oral contraceptive pill. HR is 108 bpm, BP 124/80 mmHg, SpO2 94% on air. Her chest is clear. Two-level Wells score is 6. CXR is normal. ECG shows sinus tachycardia. She has no contraindications to anticoagulation. Her eGFR is normal. What is the SINGLE most appropriate next step?', 'NICE NG158: Wells score over 4 means PE is likely; arrange CTPA (D-dimer is not needed). If CTPA is delayed, start interim anticoagulation. Treat for at least 3 months, and stop the combined pill.', null, true, true, jsonb_build_object('source', 'plab1-xlsx-v7', 'guidelines_text', 'NICE NG158; Wells')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('19942795-47ea-5a7c-89b0-12ae2f9876a7', '74e5b747-968a-5706-97c6-e4a1288d19ae', 'A', 'Start aspirin', false, 0),
  ('0bffefe9-3454-5e7d-9594-b2530c9f722e', '74e5b747-968a-5706-97c6-e4a1288d19ae', 'B', 'Echocardiogram only', false, 1),
  ('0db5aafd-c51e-5be8-b304-0d392bffe60e', '74e5b747-968a-5706-97c6-e4a1288d19ae', 'C', 'D-dimer first and only image if positive', false, 2),
  ('80413dae-4c4f-5e15-a83e-591cc0b4335d', '74e5b747-968a-5706-97c6-e4a1288d19ae', 'D', 'Discharge with analgesia', false, 3),
  ('4f1f7a49-32e9-598c-89aa-e46ee72a224e', '74e5b747-968a-5706-97c6-e4a1288d19ae', 'E', 'Arrange CTPA immediately and start interim anticoagulation (e.g. apixaban) if there is a delay', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('58c71d61-2a60-5a4f-8507-4ed0dc27953b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 45 year old man with a long history of alcohol misuse is admitted with jaundice, fever and tender hepatomegaly. He drank heavily until 1 week ago. Blood tests show bilirubin 280 micromol/L, ALT 110 U/L, AST 260 U/L, prothrombin time prolonged, WCC 16 x 10^9/L. Glasgow alcoholic hepatitis score is 9. Ultrasound shows no biliary obstruction. Blood and urine cultures are negative. What is the SINGLE most appropriate additional treatment?', 'Alcoholic hepatitis: AST:ALT ratio over 2, fever, jaundice and leucocytosis. Severity: Maddrey discriminant function of 32 or more or Glasgow score of 9 or more. Prednisolone may improve short-term survival once infection and GI bleeding are excluded. Thiamine and alcohol withdrawal management (chlordiazepoxide).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('be0372b2-8e78-5b87-b29d-27b55d15fab1', '58c71d61-2a60-5a4f-8507-4ed0dc27953b', 'A', 'Paracetamol', false, 0),
  ('2e24e0eb-9a3a-5fc1-a3e7-67c40c622f86', '58c71d61-2a60-5a4f-8507-4ed0dc27953b', 'B', 'Prednisolone (in severe alcoholic hepatitis), with nutritional support and alcohol withdrawal management', true, 1),
  ('0ad35976-6c44-5537-965e-8777e34d99aa', '58c71d61-2a60-5a4f-8507-4ed0dc27953b', 'C', 'IV antibiotics only', false, 2),
  ('3f8012c7-4ca8-540e-9258-0831283b40d8', '58c71d61-2a60-5a4f-8507-4ed0dc27953b', 'D', 'Liver transplant immediately', false, 3),
  ('e969f0b5-bd73-5cc0-a14c-111ce35ac5b9', '58c71d61-2a60-5a4f-8507-4ed0dc27953b', 'E', 'ERCP', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8af54df8-3b25-544e-9c26-0082671c4e13', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 72 year old woman is admitted with sudden severe abdominal pain that is out of proportion to examination findings. She has atrial fibrillation and stopped her apixaban 2 weeks ago. Her abdomen is soft and only mildly tender. HR 115 bpm (irregular), BP 104/68 mmHg. Lactate is 6.2 mmol/L. WCC 20 x 10^9/L. What is the SINGLE most appropriate investigation?', 'Acute mesenteric ischaemia: pain out of proportion to signs, often in AF, with raised lactate. CT angiography is the investigation of choice. Treatment: resuscitation, heparin, and urgent revascularisation and/or laparotomy with resection of dead bowel. Mortality is high.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7a7f13a8-5214-50ef-bc95-7b367ac343a2', '8af54df8-3b25-544e-9c26-0082671c4e13', 'A', 'Ultrasound abdomen', false, 0),
  ('3c599132-0ce7-5eb2-a050-0c8ec5996c98', '8af54df8-3b25-544e-9c26-0082671c4e13', 'B', 'Upper GI endoscopy', false, 1),
  ('948c0d35-9a41-557e-9221-bd326bb4294f', '8af54df8-3b25-544e-9c26-0082671c4e13', 'C', 'Colonoscopy', false, 2),
  ('9ea46fc5-621f-5944-a572-9b60388fd9c7', '8af54df8-3b25-544e-9c26-0082671c4e13', 'D', 'CT angiography of the abdomen', true, 3),
  ('aeaa853e-18fd-557d-b883-a3dae25cac6e', '8af54df8-3b25-544e-9c26-0082671c4e13', 'E', 'Abdominal X-ray', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e427dff8-f949-5019-9862-9e3bfa104b1f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 28 year old woman with Crohn''s disease presents with 8 bloody stools a day for 5 days. She has abdominal pain. Temperature 38.1 °C, HR 104 bpm. Blood tests: Hb 102 g/L, CRP 95 mg/L, albumin 28 g/L. Stool culture and C. difficile toxin are negative. Abdominal X-ray shows the transverse colon is 5 cm in diameter. She is on azathioprine. What is the SINGLE most appropriate initial management?', 'Acute severe colitis (Truelove and Witts) needs admission, IV steroids, fluids, electrolytes and LMWH (high VTE risk). Avoid antimotility drugs and opioids (toxic megacolon). If no response by day 3, rescue therapy (infliximab or ciclosporin) or colectomy. Colon over 5.5-6 cm suggests toxic megacolon.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('3ee5c566-8787-5aca-88fd-48d3551bf003', 'e427dff8-f949-5019-9862-9e3bfa104b1f', 'A', 'Oral mesalazine and discharge', false, 0),
  ('eb1afc01-bd03-59fb-9ca2-c59c0b4483c0', 'e427dff8-f949-5019-9862-9e3bfa104b1f', 'B', 'Loperamide to reduce diarrhoea', false, 1),
  ('e91a2325-0245-5975-94ce-1b340cf30c4c', 'e427dff8-f949-5019-9862-9e3bfa104b1f', 'C', 'Admit, IV hydrocortisone, VTE prophylaxis (LMWH) and daily review with gastroenterology and surgery', true, 2),
  ('6eebd17c-4ce2-5671-8488-69d7352c09b9', 'e427dff8-f949-5019-9862-9e3bfa104b1f', 'D', 'Immediate colectomy', false, 3),
  ('e0e59a31-6e3d-5acd-abcd-d2deb152a510', 'e427dff8-f949-5019-9862-9e3bfa104b1f', 'E', 'Oral antibiotics only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('71c16057-53b7-5273-bc4c-4db7d2c02d12', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000003', 'sba', 'A 55 year old man presents with 2 days of vomiting fresh blood after a binge of alcohol. Before the bleeding he vomited several times without blood. His HR is 98 bpm and BP is 126/80 mmHg. Hb is 138 g/L and urea is 6.8 mmol/L. He has no signs of liver disease. Glasgow-Blatchford score is 1. What is the SINGLE most likely diagnosis?', 'Mallory-Weiss tears are mucosal tears at the gastro-oesophageal junction after forceful vomiting. Most stop bleeding spontaneously. Glasgow-Blatchford score of 0 can be managed as an outpatient; low scores may have early outpatient endoscopy. Boerhaave syndrome (full-thickness rupture) causes severe chest pain and surgical emphysema.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4b34b9ab-a90b-57f3-9d30-5120229807a7', '71c16057-53b7-5273-bc4c-4db7d2c02d12', 'A', 'Peptic ulcer', false, 0),
  ('a22d719c-327a-524f-a4b3-90687121a047', '71c16057-53b7-5273-bc4c-4db7d2c02d12', 'B', 'Mallory-Weiss tear', true, 1),
  ('79d0f025-d37d-5e51-b25b-ee54dfbc7bf8', '71c16057-53b7-5273-bc4c-4db7d2c02d12', 'C', 'Boerhaave syndrome', false, 2),
  ('1273e607-057c-5d14-9ff9-ba2c95a88627', '71c16057-53b7-5273-bc4c-4db7d2c02d12', 'D', 'Oesophageal cancer', false, 3),
  ('5fb36907-8d32-506a-b994-21175b687425', '71c16057-53b7-5273-bc4c-4db7d2c02d12', 'E', 'Oesophageal varices', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('82284d07-323d-5355-b893-42419a2369c9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 19 year old woman with type 1 diabetes presents with vomiting and abdominal pain for 1 day. She has missed insulin doses. She is drowsy. HR 122 bpm, BP 96/60 mmHg, RR 30/min (deep). Capillary glucose is 28 mmol/L, blood ketones 5.8 mmol/L. Venous gas: pH 7.08, HCO3- 8 mmol/L, K+ 5.6 mmol/L. What is the SINGLE most appropriate insulin regimen?', 'DKA (JBDS): IV 0.9% saline, fixed-rate IV insulin infusion 0.1 units/kg/hour, continue basal insulin. Add potassium to fluids when K+ is under 5.5. Add 10% dextrose when glucose falls below 14. Aim for ketone fall of 0.5 mmol/L/hour. Watch for cerebral oedema in young people.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7', 'guidelines_text', 'JBDS')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('641b869c-770e-52f5-b6f8-2994adb8aace', '82284d07-323d-5355-b893-42419a2369c9', 'A', 'Withhold insulin until potassium falls below 4', false, 0),
  ('0b6e5a58-5693-5148-b642-35fa0689fb67', '82284d07-323d-5355-b893-42419a2369c9', 'B', 'Fixed-rate IV insulin infusion at 0.1 units/kg/hour, with continuation of her long-acting insulin', true, 1),
  ('6e68ecff-7d46-587c-a24d-8457ae51ad07', '82284d07-323d-5355-b893-42419a2369c9', 'C', 'IV insulin bolus of 20 units then stop', false, 2),
  ('38459e0c-3dcd-5174-a9f6-6fd8b2f73cdc', '82284d07-323d-5355-b893-42419a2369c9', 'D', 'SC rapid-acting insulin 4-hourly', false, 3),
  ('3e2c3e10-2f65-57f2-8e44-1345303f8a21', '82284d07-323d-5355-b893-42419a2369c9', 'E', 'Variable-rate infusion based on glucose only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e6e8205e-4d2c-5b18-aea8-662d33b903a8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 78 year old man with type 2 diabetes is brought in by his carer with confusion and reduced intake for 5 days after a chest infection. He is severely dehydrated. Glucose is 52 mmol/L, Na+ 156 mmol/L, urea 24 mmol/L, blood ketones 0.8 mmol/L, pH 7.34. Calculated serum osmolality is 384 mOsm/kg. What is the SINGLE most appropriate initial treatment?', 'Hyperosmolar hyperglycaemic state: severe hyperglycaemia, osmolality over 320, little ketosis. Fluids alone lower glucose. Avoid rapid changes in osmolality (cerebral oedema, osmotic demyelination): aim for osmolality fall of 3-8 mOsm/kg/hour. High risk of VTE (LMWH) and foot ulcers.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('477e9762-54a4-540e-8df5-522e9eb2ffc6', 'e6e8205e-4d2c-5b18-aea8-662d33b903a8', 'A', 'Hypotonic 0.45% saline first', false, 0),
  ('3906e6a0-5fac-58dd-bcf3-5de2fa890b44', 'e6e8205e-4d2c-5b18-aea8-662d33b903a8', 'B', 'Fixed-rate insulin at 0.1 units/kg/hour immediately', false, 1),
  ('7022dd0f-cce0-5564-bdbb-44f332c49a44', 'e6e8205e-4d2c-5b18-aea8-662d33b903a8', 'C', 'Oral fluids only', false, 2),
  ('f651af39-6092-5c2e-a056-f3eb8c6bde25', 'e6e8205e-4d2c-5b18-aea8-662d33b903a8', 'D', 'IV 5% dextrose', false, 3),
  ('b3868da9-5334-58d3-a682-4f6ec098f188', 'e6e8205e-4d2c-5b18-aea8-662d33b903a8', 'E', 'IV 0.9% sodium chloride to restore volume, with low-dose insulin only once glucose stops falling with fluids alone (or if ketonaemia)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('621e2909-659f-56cf-95cf-d2171201a034', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 42 year old woman presents with tiredness, weight loss, dizziness on standing and salt craving for 3 months. She has vitiligo and hypothyroidism. Her skin is darker, especially on her palmar creases and gums. BP lying is 104/66 mmHg, and standing is 84/52 mmHg. Blood tests: Na+ 128 mmol/L, K+ 5.6 mmol/L, glucose 3.8 mmol/L. 9 am cortisol is 90 nmol/L. What is the SINGLE most appropriate confirmatory test?', 'Primary adrenal insufficiency (Addison''s disease) is usually autoimmune (associated with other autoimmune conditions). Hyperpigmentation results from high ACTH. Short Synacthen test confirms. Treatment: hydrocortisone and fludrocortisone, sick-day rules and an emergency steroid card and kit.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('50edc30e-863b-589d-855a-d50a347183e4', '621e2909-659f-56cf-95cf-d2171201a034', 'A', 'Insulin tolerance test in all', false, 0),
  ('fe93efc5-a150-51ef-b57b-f381f4d2672e', '621e2909-659f-56cf-95cf-d2171201a034', 'B', 'CT adrenals first', false, 1),
  ('ef9b5448-84e2-5863-b790-5c69b0bd5de8', '621e2909-659f-56cf-95cf-d2171201a034', 'C', 'Short Synacthen test (ACTH stimulation test)', true, 2),
  ('de21a4dc-b6a7-57ef-96b9-550eda398b57', '621e2909-659f-56cf-95cf-d2171201a034', 'D', 'Aldosterone-renin ratio', false, 3),
  ('147a6a34-1158-5ca0-88f1-037c951b3079', '621e2909-659f-56cf-95cf-d2171201a034', 'E', 'Dexamethasone suppression test', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7dc22bbe-dbfa-5a5e-a10f-31b6ec728a58', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 56 year old woman presents with weight gain, easy bruising and high BP for 1 year. She has a round face, a fat pad between her shoulders, purple striae on her abdomen and proximal muscle weakness. Her glucose is raised. She does not take steroids. Overnight dexamethasone suppression test shows cortisol is not suppressed. ACTH is undetectable. What is the SINGLE most likely cause?', 'Cushing''s syndrome: screen with overnight dexamethasone suppression test, 24-hour urinary free cortisol or late-night salivary cortisol. Low ACTH means adrenal cause (adenoma or carcinoma): CT adrenals. High ACTH means pituitary (high-dose dexamethasone suppression) or ectopic source.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('88bd54ef-da0c-5ed6-9d61-1f03112f7b27', '7dc22bbe-dbfa-5a5e-a10f-31b6ec728a58', 'A', 'Ectopic ACTH from small cell lung cancer', false, 0),
  ('15fbf2f4-6c79-55fd-b69c-5e29500d6c47', '7dc22bbe-dbfa-5a5e-a10f-31b6ec728a58', 'B', 'Adrenal adenoma (ACTH-independent Cushing''s syndrome)', true, 1),
  ('32204e0b-1b42-57bb-8305-33b435aef0c5', '7dc22bbe-dbfa-5a5e-a10f-31b6ec728a58', 'C', 'Pseudo-Cushing''s from alcohol', false, 2),
  ('3753f3e6-7e3e-5341-8a4e-afc81a5057d3', '7dc22bbe-dbfa-5a5e-a10f-31b6ec728a58', 'D', 'Exogenous steroids', false, 3),
  ('fda97949-d2ff-5fa0-9d0c-497bcd2a865d', '7dc22bbe-dbfa-5a5e-a10f-31b6ec728a58', 'E', 'Pituitary adenoma (Cushing''s disease)', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f7065cb6-b59d-5546-bc89-bae49fdebae6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 70 year old man is admitted with a 3-day history of diarrhoea and vomiting. He takes ramipril, furosemide, metformin and naproxen. He is dry, HR 104 bpm, BP 92/56 mmHg. Creatinine is 320 micromol/L (baseline 110), K+ 6.4 mmol/L. ECG shows tall tented T waves and a broadened QRS. What is the SINGLE most appropriate immediate treatment?', 'Hyperkalaemia with ECG changes: IV calcium (stabilises the myocardium, does not lower K+), then insulin-dextrose and nebulised salbutamol to shift K+, then remove K+ (potassium binders, dialysis). Stop nephrotoxic and hyperkalaemic drugs (sick-day rules: ACE inhibitor, diuretics, metformin, NSAIDs). Fluids for pre-renal AKI.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/Combined_hyperkalemia_and_hypocalcemia.png')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('258533c8-f5d7-5888-915f-51adf25f943e', 'f7065cb6-b59d-5546-bc89-bae49fdebae6', 'A', 'IV furosemide', false, 0),
  ('01b8dd44-9b07-547d-a549-2037933f5ebe', 'f7065cb6-b59d-5546-bc89-bae49fdebae6', 'B', 'Oral calcium resonium only', false, 1),
  ('e62ef19d-4b70-57a1-9301-2595a42b033d', 'f7065cb6-b59d-5546-bc89-bae49fdebae6', 'C', 'Haemodialysis before any drug treatment', false, 2),
  ('4896e2ea-971e-56a7-aed6-03795d39f6df', 'f7065cb6-b59d-5546-bc89-bae49fdebae6', 'D', 'IV calcium gluconate 10% (30 mL) to stabilise the myocardium', true, 3),
  ('c79281d9-3df5-5945-9730-0d73cb988e23', 'f7065cb6-b59d-5546-bc89-bae49fdebae6', 'E', 'IV insulin-dextrose first, before calcium', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9de57c87-b646-50fe-b196-bfaf38a64dd9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 64 year old woman has had fatigue, a rash and joint pain for a week. She started a new antibiotic 10 days ago for a chest infection. She also takes omeprazole. Her creatinine has risen from 80 to 260 micromol/L. Urine dipstick shows leucocytes 2+ and protein 1+ but cultures are negative. Blood tests show eosinophilia. What is the SINGLE most likely diagnosis?', 'Drug-induced AIN: fever, rash, eosinophilia, sterile pyuria and AKI. Common causes: PPIs, NSAIDs, penicillins and other antibiotics. Stop the drug. Steroids may help if renal function does not improve. Renal biopsy confirms.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e5730c85-fb39-5509-b92d-ce5645c05deb', '9de57c87-b646-50fe-b196-bfaf38a64dd9', 'A', 'Acute tubular necrosis', false, 0),
  ('c724ebff-e516-5af9-8603-7d74085ddfd0', '9de57c87-b646-50fe-b196-bfaf38a64dd9', 'B', 'Post-infectious glomerulonephritis', false, 1),
  ('fdb1165b-2b84-53f6-82d3-a422d5040ad2', '9de57c87-b646-50fe-b196-bfaf38a64dd9', 'C', 'Renal artery stenosis', false, 2),
  ('11a7f55f-a937-5aae-87a1-fba312dafdf5', '9de57c87-b646-50fe-b196-bfaf38a64dd9', 'D', 'Pyelonephritis', false, 3),
  ('15c19463-3f94-5687-a6e4-ef07337c3c95', '9de57c87-b646-50fe-b196-bfaf38a64dd9', 'E', 'Acute interstitial nephritis', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2fc98601-379b-526c-86d8-8a9320dbcb6e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000005', 'sba', 'A 38 year old man has had loin pain and visible haematuria. His BP is 162/98 mmHg. His father had kidney failure and died of a brain haemorrhage at 50. On examination there are bilateral ballotable masses in the flanks. Ultrasound shows bilateral enlarged kidneys with multiple cysts and a few liver cysts. eGFR is 52. What is the SINGLE most likely diagnosis?', 'ADPKD (PKD1, PKD2) causes hypertension, haematuria, pain, infections and CKD. Associated with intracranial berry aneurysms, liver cysts and mitral valve prolapse. Control BP (ACE inhibitor). Tolvaptan slows progression in rapidly progressing disease. Screen relatives with ultrasound.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cb7cf2c5-b6a3-594b-af6c-16d69d540db9', '2fc98601-379b-526c-86d8-8a9320dbcb6e', 'A', 'Renal cell carcinoma', false, 0),
  ('b000ed2c-eb20-5aab-aa4c-2739a61cdafe', '2fc98601-379b-526c-86d8-8a9320dbcb6e', 'B', 'Autosomal dominant polycystic kidney disease', true, 1),
  ('ef99617e-2a45-5d52-b192-b6dc9d1cc2dd', '2fc98601-379b-526c-86d8-8a9320dbcb6e', 'C', 'Autosomal recessive polycystic kidney disease', false, 2),
  ('74616f0d-d963-56d9-b8fb-91b9d3f81953', '2fc98601-379b-526c-86d8-8a9320dbcb6e', 'D', 'Simple renal cysts', false, 3),
  ('af2d92c0-c7db-5eb4-810f-53a25fb5aba0', '2fc98601-379b-526c-86d8-8a9320dbcb6e', 'E', 'Tuberous sclerosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('fd7f7418-4c89-5ac8-91c5-0b45362edf4b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 68 year old man has had back pain for 3 months, tiredness and recurrent chest infections. Blood tests: Hb 92 g/L, calcium 2.95 mmol/L, creatinine 180 micromol/L, total protein 98 g/L, albumin 32 g/L. ESR is 110. X-ray of the spine shows osteopenia with a collapsed vertebra. Skull X-ray shows multiple lytic ''pepper-pot'' lesions. What is the SINGLE most appropriate test to confirm the diagnosis?', 'Multiple myeloma: CRAB features (hypercalcaemia, renal impairment, anaemia, bone lesions). Investigations: serum protein electrophoresis and immunofixation, free light chains, urine Bence Jones protein, bone marrow, and whole-body low-dose CT or MRI. Bone scans may be normal (lytic lesions).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('fc6bc35f-6ea7-5476-abf7-62a08cef2c06', 'fd7f7418-4c89-5ac8-91c5-0b45362edf4b', 'A', 'CT chest only', false, 0),
  ('98653dc0-61fa-5733-a7cc-79bc544106ba', 'fd7f7418-4c89-5ac8-91c5-0b45362edf4b', 'B', 'Bence Jones protein alone in all', false, 1),
  ('a5aca0ba-f41d-5954-b2d5-0443258a7f5a', 'fd7f7418-4c89-5ac8-91c5-0b45362edf4b', 'C', 'Serum free light chains and protein electrophoresis, with bone marrow biopsy', true, 2),
  ('0bab1da4-f560-549f-9830-1895a789e2ef', 'fd7f7418-4c89-5ac8-91c5-0b45362edf4b', 'D', 'PSA', false, 3),
  ('db6c3613-228f-5d31-a23b-49a96f2ea911', 'fd7f7418-4c89-5ac8-91c5-0b45362edf4b', 'E', 'Bone scan', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('11f78e2a-f4b6-5928-8e86-81d49c5302d7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 30 year old woman is 2 days after a caesarean section. She has a fever and has been bleeding from her wound, IV cannula sites and gums. Platelets are 40 x 10^9/L, prothrombin time and APTT are prolonged, fibrinogen is 0.9 g/L and D-dimer is very high. Blood film shows fragmented red cells. What is the SINGLE most likely diagnosis?', 'DIC: consumption of clotting factors and platelets with low fibrinogen and high D-dimer. Causes: sepsis, obstetric complications, trauma, malignancy. Treat the cause; give platelets, FFP and cryoprecipitate if bleeding.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('510cd30b-e925-5b5f-a892-30da302b38db', '11f78e2a-f4b6-5928-8e86-81d49c5302d7', 'A', 'Disseminated intravascular coagulation (likely due to sepsis)', true, 0),
  ('92ca43eb-b9de-5ab1-986b-6e22e7e673cd', '11f78e2a-f4b6-5928-8e86-81d49c5302d7', 'B', 'ITP', false, 1),
  ('da90fe76-df5f-5535-b20b-552674a8998b', '11f78e2a-f4b6-5928-8e86-81d49c5302d7', 'C', 'TTP', false, 2),
  ('fd0190b1-e595-53d2-8a1c-1880092a7d97', '11f78e2a-f4b6-5928-8e86-81d49c5302d7', 'D', 'Haemophilia', false, 3),
  ('96d02256-e718-5796-a495-d35027c32cec', '11f78e2a-f4b6-5928-8e86-81d49c5302d7', 'E', 'Vitamin K deficiency', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3d0f37a0-21f3-5dd7-98e5-1140cf5374f0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000014', 'sba', 'A 72 year old man has had bruising, recurrent infections and tiredness for 2 months. He is pale with gum hypertrophy. Blood tests: Hb 78 g/L, WCC 68 x 10^9/L, platelets 22 x 10^9/L. Blood film shows many blasts with Auer rods. What is the SINGLE most likely diagnosis?', 'AML occurs mostly in older adults. Auer rods are characteristic. Gum infiltration suggests monocytic subtype. Acute promyelocytic leukaemia (t(15;17)) causes DIC and is treated with all-trans retinoic acid. Same-day referral for suspected acute leukaemia.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5c2f6237-9350-564b-af01-2452755e2de6', '3d0f37a0-21f3-5dd7-98e5-1140cf5374f0', 'A', 'Acute lymphoblastic leukaemia', false, 0),
  ('8d30a538-cafc-5386-8466-6bac3b7612eb', '3d0f37a0-21f3-5dd7-98e5-1140cf5374f0', 'B', 'Acute myeloid leukaemia', true, 1),
  ('44434361-8987-55fe-8da6-068d34b19a79', '3d0f37a0-21f3-5dd7-98e5-1140cf5374f0', 'C', 'Chronic lymphocytic leukaemia', false, 2),
  ('7b8e545c-638b-5121-938a-5b57453fdcf7', '3d0f37a0-21f3-5dd7-98e5-1140cf5374f0', 'D', 'Chronic myeloid leukaemia', false, 3),
  ('b82b701c-6e9f-572c-b074-dc7fbc50f9bf', '3d0f37a0-21f3-5dd7-98e5-1140cf5374f0', 'E', 'Myelodysplastic syndrome', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('bab4f268-74fc-57a8-8bbf-96fd061dad58', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 31 year old man returned from Ghana 10 days ago. He did not take malaria prophylaxis. He has had a fever, rigors, headache and vomiting for 3 days. He is now confused. Temperature 39.6 °C, HR 120 bpm, BP 96/60 mmHg. Blood tests: Hb 88 g/L, platelets 40 x 10^9/L, creatinine 260 micromol/L, glucose 3.1 mmol/L. Thick and thin films show 8% parasitaemia with Plasmodium falciparum. What is the SINGLE most appropriate treatment?', 'Severe falciparum malaria: impaired consciousness, parasitaemia over 2%, renal impairment, hypoglycaemia, acidosis, shock or severe anaemia. IV artesunate is first-line. Monitor glucose. Switch to oral artemisinin combination therapy when improved. Notifiable.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f3c7bf15-cb09-5f8a-bf8c-1d4a61e6b423', 'bab4f268-74fc-57a8-8bbf-96fd061dad58', 'A', 'Oral primaquine', false, 0),
  ('6d2453b4-3ad0-5429-a8cd-2aa7bafc1475', 'bab4f268-74fc-57a8-8bbf-96fd061dad58', 'B', 'IV artesunate', true, 1),
  ('bb6f2f41-36ab-5432-92af-35e291b7fbb5', 'bab4f268-74fc-57a8-8bbf-96fd061dad58', 'C', 'Oral artemether-lumefantrine', false, 2),
  ('e10fedde-4969-5252-9e65-c1e91d2b78e6', 'bab4f268-74fc-57a8-8bbf-96fd061dad58', 'D', 'Oral chloroquine', false, 3),
  ('a76633e4-024d-5a5b-b003-dccf957fd500', 'bab4f268-74fc-57a8-8bbf-96fd061dad58', 'E', 'IV quinine only after waiting for repeat films', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('fa5c52e4-82ef-5e69-af81-b3ce6b85960e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 35 year old man with HIV, not on treatment, has had a dry cough and breathlessness on exertion for 3 weeks. He is short of breath on walking. Temperature 37.9 °C. SpO2 is 95% at rest and falls to 86% on exercise. CXR shows bilateral perihilar ground-glass shadowing. His CD4 count is 90 cells/microlitre. What is the SINGLE most appropriate treatment?', 'Pneumocystis pneumonia occurs with CD4 under 200. Exercise desaturation is typical. Confirm by induced sputum or bronchoalveolar lavage. Pneumothorax is a complication. Prophylaxis with co-trimoxazole for CD4 under 200. Start antiretroviral therapy within 2 weeks.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ee83110d-7394-5e1c-be74-ad245f425344', 'fa5c52e4-82ef-5e69-af81-b3ce6b85960e', 'A', 'Clarithromycin only', false, 0),
  ('ad4957d7-cb0d-51a1-b576-18f782a330dd', 'fa5c52e4-82ef-5e69-af81-b3ce6b85960e', 'B', 'Fluconazole', false, 1),
  ('0fba114e-85bc-59b1-ac82-a06ed9a9f6f0', 'fa5c52e4-82ef-5e69-af81-b3ce6b85960e', 'C', 'Anti-TB treatment', false, 2),
  ('e6e4c6cf-1d60-5c90-9e57-a97b6923dd46', 'fa5c52e4-82ef-5e69-af81-b3ce6b85960e', 'D', 'High-dose co-trimoxazole, with steroids if PaO2 is under 9.3 kPa', true, 3),
  ('d714cf58-5c11-5907-91c7-6987b726131c', 'fa5c52e4-82ef-5e69-af81-b3ce6b85960e', 'E', 'Amoxicillin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('51b57117-374a-5dc6-8385-26ae35a9b7b5', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 26 year old man has had a fever, headache and drowsiness for 12 hours. He now has a non-blanching purpuric rash on his legs and trunk. HR 130 bpm, BP 82/50 mmHg, capillary refill 5 seconds. He is drowsy but responds to voice. He has no drug allergies. What is the SINGLE most appropriate immediate management?', 'Meningococcal septicaemia is an emergency. Give IV ceftriaxone (or IM benzylpenicillin pre-hospital) without delay. Take blood cultures but do not delay antibiotics. LP is contraindicated in shock, purpura or raised ICP. Notify UKHSA; close contacts get ciprofloxacin prophylaxis.', null, true, true, jsonb_build_object('source', 'plab1-xlsx-v7', 'guidelines_text', 'UKHSA')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0bb297a8-9362-5e70-a45d-aa89fd694f88', '51b57117-374a-5dc6-8385-26ae35a9b7b5', 'A', 'CT head first, then antibiotics', false, 0),
  ('f8263d0f-280c-5739-b66c-bae12120fa2a', '51b57117-374a-5dc6-8385-26ae35a9b7b5', 'B', 'IV ceftriaxone immediately (do not delay for lumbar puncture), with fluid resuscitation and senior help', true, 1),
  ('96f95471-a951-5221-90e9-e443c1e89e40', '51b57117-374a-5dc6-8385-26ae35a9b7b5', 'C', 'Wait for blood cultures before antibiotics', false, 2),
  ('b6aff804-0454-5a07-b553-2eae423df095', '51b57117-374a-5dc6-8385-26ae35a9b7b5', 'D', 'Oral penicillin and review', false, 3),
  ('e45c1ae9-5ba6-5a0d-b775-ce8c0330fbd4', '51b57117-374a-5dc6-8385-26ae35a9b7b5', 'E', 'Lumbar puncture first', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2a635adf-b1c0-5a1a-b92f-2c3336a19026', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 68 year old man is in hospital receiving IV co-amoxiclav for pneumonia. On day 5 he develops 8 episodes of watery diarrhoea a day, abdominal pain and a fever of 38.4 °C. His WCC is 18 x 10^9/L and creatinine has risen. Stool tests are positive for C. difficile toxin. It is his first episode. What is the SINGLE most appropriate management?', 'NICE NG199: first episode C. difficile: oral vancomycin (fidaxomicin second-line). Life-threatening disease: oral vancomycin with IV metronidazole and surgical review. Alcohol gel does not kill spores. Review PPIs. Faecal microbiota transplant for recurrence.', null, true, true, jsonb_build_object('source', 'plab1-xlsx-v7', 'guidelines_text', 'NICE NG199')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('55ab9be4-6b90-563c-8125-5fc5b37fbdde', '2a635adf-b1c0-5a1a-b92f-2c3336a19026', 'A', 'IV vancomycin', false, 0),
  ('ceb9932c-60fc-5c9e-a80b-bcd4ebc047d1', '2a635adf-b1c0-5a1a-b92f-2c3336a19026', 'B', 'Loperamide', false, 1),
  ('af167e60-0bb0-502d-8582-99cc09550b49', '2a635adf-b1c0-5a1a-b92f-2c3336a19026', 'C', 'Oral metronidazole in all cases', false, 2),
  ('3f75a7fe-2ef7-5d50-b33c-5f785d507526', '2a635adf-b1c0-5a1a-b92f-2c3336a19026', 'D', 'Probiotics only', false, 3),
  ('9ec48b71-3901-57f1-8112-0347daf0de63', '2a635adf-b1c0-5a1a-b92f-2c3336a19026', 'E', 'Oral vancomycin for 10 days, stop co-amoxiclav if possible, isolate him and use soap and water hand hygiene', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f20c23cc-d9ad-59fe-bc8a-2ccc4df4b483', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 34 year old woman gave birth 6 days ago. Her partner is worried because she has not slept for 3 days, is talking very fast and believes the baby has been swapped by the hospital and that she has a special mission from God. She is agitated and has been seen whispering to the baby that they must ''escape together''. She has a history of bipolar disorder and stopped lithium in pregnancy. What is the SINGLE most appropriate management?', 'Postpartum psychosis is a psychiatric emergency, usually starting within 2 weeks of delivery. Bipolar disorder is the major risk factor. Risk to mother and baby (suicide, infanticide). Admit to a mother and baby unit, and treat with antipsychotics, mood stabilisers or ECT.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c5fa1f42-9356-5cc3-b32f-603cd471fc86', 'f20c23cc-d9ad-59fe-bc8a-2ccc4df4b483', 'A', 'Start sertraline and review in a month', false, 0),
  ('51ae7b35-1055-560b-a29f-d8b0133e684b', 'f20c23cc-d9ad-59fe-bc8a-2ccc4df4b483', 'B', 'Urgent admission to a mother and baby psychiatric unit', true, 1),
  ('81e04aa5-e18d-54f5-a147-9933b1b5cd37', 'f20c23cc-d9ad-59fe-bc8a-2ccc4df4b483', 'C', 'CBT referral', false, 2),
  ('0bd25c34-de3b-5feb-bccf-d7bbc58b3062', 'f20c23cc-d9ad-59fe-bc8a-2ccc4df4b483', 'D', 'GP follow-up in 2 weeks', false, 3),
  ('ab96bb59-cdb9-5bc0-95a6-a22acd7dfe1e', 'f20c23cc-d9ad-59fe-bc8a-2ccc4df4b483', 'E', 'Reassure; this is the ''baby blues''', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a1245232-84a6-5b48-a74f-eb87f589b04e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 46 year old man is brought to the emergency department by his wife. He has been drinking 30 units of alcohol a day and stopped 2 days ago. He is sweating, agitated and tremulous. He is seeing insects crawling on the walls and does not know where he is. HR 124 bpm, BP 168/100 mmHg, temperature 38.0 °C. What is the SINGLE most likely diagnosis and initial treatment?', 'Delirium tremens usually occurs 48-72 hours after the last drink: confusion, visual hallucinations, autonomic hyperactivity and seizures. It is a medical emergency. Treat with benzodiazepines (lorazepam IV if unable to take oral), IV Pabrinex, fluids and electrolyte correction. Avoid antipsychotics alone (lower seizure threshold).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('fe0fb943-ecf2-5517-9400-e3c4e542d3ea', 'a1245232-84a6-5b48-a74f-eb87f589b04e', 'A', 'Hypoglycaemia; glucagon', false, 0),
  ('cff0ecf2-31d3-5e95-9797-2350c51afbca', 'a1245232-84a6-5b48-a74f-eb87f589b04e', 'B', 'Schizophrenia; haloperidol alone', false, 1),
  ('80fadba8-fdc4-5c1a-ac79-f67c6c93052f', 'a1245232-84a6-5b48-a74f-eb87f589b04e', 'C', 'Sepsis; antibiotics only', false, 2),
  ('b804cbb2-24c0-5f87-a830-10ce78ab21e1', 'a1245232-84a6-5b48-a74f-eb87f589b04e', 'D', 'Delirium tremens; oral or IV benzodiazepines (e.g. lorazepam or chlordiazepoxide) and IV thiamine', true, 3),
  ('ea2c30af-2179-524f-991f-f7dcee6c25fb', 'a1245232-84a6-5b48-a74f-eb87f589b04e', 'E', 'Wernicke''s encephalopathy; glucose', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('1c1c074b-fc08-5e1f-ab77-d2f6e7fea957', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000007', 'sba', 'A 52 year old man has had low mood for 6 months. He lost his job and his marriage ended. He has stopped eating and lost 8 kg. He wakes at 4 am, cannot concentrate and feels hopeless. He believes his body is rotting from the inside and that he deserves to die. He has given away his belongings. He has no previous psychiatric history. What is the SINGLE most appropriate management?', 'Severe depression with psychotic features (nihilistic delusions) and high-risk features (male, unemployed, separated, giving away belongings, hopelessness) needs urgent crisis team assessment. Treatment: antidepressant with antipsychotic; ECT is effective for severe or psychotic depression, or when life-threatening.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0226b10e-f129-5b30-b49a-117568a2df48', '1c1c074b-fc08-5e1f-ab77-d2f6e7fea957', 'A', 'Discharge with leaflet', false, 0),
  ('b80150f7-a3eb-5b62-9f6b-b6ee5aa57017', '1c1c074b-fc08-5e1f-ab77-d2f6e7fea957', 'B', 'Guided self-help', false, 1),
  ('ab768bf4-5e39-5d72-95d1-69cb49460a28', '1c1c074b-fc08-5e1f-ab77-d2f6e7fea957', 'C', 'Urgent psychiatric referral (crisis team) for severe depression with psychotic features and high suicide risk', true, 2),
  ('08e89971-6992-595b-bc4d-a0d5dd771ea2', '1c1c074b-fc08-5e1f-ab77-d2f6e7fea957', 'D', 'GP review in 4 weeks', false, 3),
  ('171b0d2b-aa76-5c74-9cab-6b28012cb393', '1c1c074b-fc08-5e1f-ab77-d2f6e7fea957', 'E', 'Start sertraline and review in 6 weeks only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6f937f9e-1f6c-5ef4-8fe9-a95e02685e4d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 74 year old woman has had colicky abdominal pain, distension and vomiting for 2 days. She has not opened her bowels or passed wind for 2 days. She had a hysterectomy 20 years ago. Her abdomen is distended and tympanic with high-pitched bowel sounds. There is no tenderness or guarding. HR 98 bpm. Lactate is normal. Abdominal X-ray shows dilated small bowel loops with valvulae conniventes. What is the SINGLE most appropriate initial management?', 'Adhesions are the commonest cause of small bowel obstruction. Without signs of strangulation (peritonism, fever, raised lactate, tachycardia), manage conservatively. Water-soluble contrast (Gastrografin) is diagnostic and may be therapeutic. Surgery if strangulation or failure to resolve.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5383ad24-a4df-5987-b0cc-e222bc1166bc', '6f937f9e-1f6c-5ef4-8fe9-a95e02685e4d', 'A', 'Immediate laparotomy', false, 0),
  ('145767a2-2fca-5610-9825-49d5daa1ef91', '6f937f9e-1f6c-5ef4-8fe9-a95e02685e4d', 'B', 'Discharge with analgesia', false, 1),
  ('6413f0d2-a928-5b8a-9cd3-099e3e974258', '6f937f9e-1f6c-5ef4-8fe9-a95e02685e4d', 'C', 'Laxatives and enemas', false, 2),
  ('dc556c8a-7d64-51a3-bfe1-395a29db32c4', '6f937f9e-1f6c-5ef4-8fe9-a95e02685e4d', 'D', 'Colonoscopy', false, 3),
  ('66d482a3-3477-54e8-b41d-4c260a6cf24e', '6f937f9e-1f6c-5ef4-8fe9-a95e02685e4d', 'E', '''Drip and suck'': IV fluids, nasogastric decompression, nil by mouth, and CT to confirm adhesional small bowel obstruction', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d01bba95-f671-5f4f-a15c-e822a2f70223', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 45 year old woman presents with severe epigastric pain radiating to the back for 12 hours with vomiting. She has gallstones. HR 112 bpm, BP 106/70 mmHg, temperature 37.8 °C. Amylase is 1,800 U/L. Glasgow score: age under 55, WCC 17, glucose 12, urea 18, PaO2 7.8 kPa, calcium 1.9 mmol/L, albumin 30, LDH 700. What is the SINGLE most appropriate management?', 'Glasgow (Imrie) score (PANCREAS): PaO2 under 8, age over 55, neutrophilia (WCC over 15), calcium under 2, raised urea over 16, enzymes (LDH over 600), albumin under 32, sugar over 10. A score of 3 or more is severe. ERCP within 72 hours if cholangitis or obstruction. Early enteral nutrition. Cholecystectomy for gallstone pancreatitis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e064c935-646c-54e5-a527-e0f279b763d3', 'd01bba95-f671-5f4f-a15c-e822a2f70223', 'A', 'Discharge with oral analgesia', false, 0),
  ('e1ed92c9-15a4-5f38-a5c1-4ea6849fecf3', 'd01bba95-f671-5f4f-a15c-e822a2f70223', 'B', 'Nil by mouth for 2 weeks', false, 1),
  ('fefbcdc9-384a-55b1-8c5e-81690ca9d04e', 'd01bba95-f671-5f4f-a15c-e822a2f70223', 'C', 'Severe pancreatitis (Glasgow score 3 or more): aggressive IV fluids, analgesia, HDU/ICU referral, and early cholecystectomy planned for the same admission once settled', true, 2),
  ('787361fc-7d6f-5928-91fb-9542abee71f2', 'd01bba95-f671-5f4f-a15c-e822a2f70223', 'D', 'Prophylactic antibiotics for all', false, 3),
  ('489f0bcb-c7a4-559a-8261-01777bc662f2', 'd01bba95-f671-5f4f-a15c-e822a2f70223', 'E', 'Immediate laparotomy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0a53524d-57ef-5c89-a7f0-6292de17f941', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000030', 'sba', 'A 68 year old man presents with left iliac fossa pain and fever for 3 days. He has had constipation. Temperature 38.4 °C, HR 102 bpm, BP 128/78 mmHg. There is tenderness in the left iliac fossa without generalised peritonism. CRP 180 mg/L, WCC 17 x 10^9/L. CT shows sigmoid diverticulitis with a 3 cm pericolic abscess. What is the SINGLE most appropriate management?', 'Complicated diverticulitis (Hinchey I-II: pericolic or pelvic abscess) is treated with IV antibiotics; abscesses over 3-4 cm may need percutaneous drainage. Hinchey III-IV (purulent or faecal peritonitis) need surgery. Colonoscopy 6 weeks later to exclude cancer.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a6567363-d79d-5e6e-9028-ad3a30be878a', '0a53524d-57ef-5c89-a7f0-6292de17f941', 'A', 'Colonoscopy now', false, 0),
  ('62ee1895-93e8-50a6-9d8b-4274e1d3e169', '0a53524d-57ef-5c89-a7f0-6292de17f941', 'B', 'Barium enema', false, 1),
  ('2b395864-8075-53cd-9c87-fb544c42901e', '0a53524d-57ef-5c89-a7f0-6292de17f941', 'C', 'Admission, IV antibiotics and percutaneous CT-guided drainage if the abscess does not respond', true, 2),
  ('6def257d-3799-5adc-9ed0-14024d9a0159', '0a53524d-57ef-5c89-a7f0-6292de17f941', 'D', 'Immediate Hartmann''s procedure', false, 3),
  ('09b62954-57f9-5bf2-9196-2ce2bd96026f', '0a53524d-57ef-5c89-a7f0-6292de17f941', 'E', 'Oral antibiotics at home', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ad084fdb-0a6d-5e76-9840-03e412490226', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 62 year old man is 2 days after a right hemicolectomy. He is drowsy and has a RR of 8/min. His pupils are pinpoint. His SpO2 is 90% on 2 L of oxygen. He has a morphine PCA. His creatinine has risen from 90 to 190 micromol/L. What is the SINGLE most appropriate management?', 'Opioid toxicity is precipitated by AKI (morphine metabolites accumulate). Naloxone has a shorter half-life than morphine, so infusion may be needed. Consider alternative opioids in renal impairment (oxycodone with caution, fentanyl or alfentanil).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7ce5aeba-12c7-578c-b135-24bd6bca62de', 'ad084fdb-0a6d-5e76-9840-03e412490226', 'A', 'Intubate immediately', false, 0),
  ('0c70110d-037d-5e6f-9410-77db2e57b305', 'ad084fdb-0a6d-5e76-9840-03e412490226', 'B', 'Increase oxygen and observe', false, 1),
  ('d6c54d8a-969f-5e9a-9ce2-d99f4018a2ab', 'ad084fdb-0a6d-5e76-9840-03e412490226', 'C', 'Give a further morphine bolus', false, 2),
  ('3c29878e-30ea-5601-a186-01bcd97f24fe', 'ad084fdb-0a6d-5e76-9840-03e412490226', 'D', 'Give flumazenil', false, 3),
  ('a4744a18-e035-503f-a382-f263eb0296dd', 'ad084fdb-0a6d-5e76-9840-03e412490226', 'E', 'Stop the PCA, give IV naloxone (titrated) and treat the AKI', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9885a24f-6d6c-5b10-bb16-34d73889eacd', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 55 year old woman is 4 days after a laparotomy for a perforated bowel. She develops a fever of 38.7 °C, a swinging temperature and abdominal pain. HR 112 bpm. WCC 19 x 10^9/L and CRP 280 mg/L. Her wound looks clean. She has had loose stools. What is the SINGLE most appropriate investigation?', 'Post-operative fever timing: day 1-2 (atelectasis, SIRS), day 3-5 (pneumonia, UTI, line infection), day 5-7 (anastomotic leak, abscess, wound infection), day 7+ (VTE). Swinging fever suggests abscess. CT abdomen; radiological drainage or re-laparotomy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a2de2015-413c-5467-9fab-ea7ce2b68390', '9885a24f-6d6c-5b10-bb16-34d73889eacd', 'A', 'Colonoscopy', false, 0),
  ('00bbdd13-d224-589f-bab4-7ed712e5435f', '9885a24f-6d6c-5b10-bb16-34d73889eacd', 'B', 'Wound swab only', false, 1),
  ('b0700134-1abd-5f1c-ba0a-234de8d20a8a', '9885a24f-6d6c-5b10-bb16-34d73889eacd', 'C', 'CT abdomen and pelvis with contrast to look for an intra-abdominal collection or anastomotic leak', true, 2),
  ('d87faf45-b951-5a0d-ac7d-fa1c27da2992', '9885a24f-6d6c-5b10-bb16-34d73889eacd', 'D', 'Abdominal X-ray only', false, 3),
  ('a4e8d8f2-7547-5c89-99e9-424b6d0e71eb', '9885a24f-6d6c-5b10-bb16-34d73889eacd', 'E', 'CXR only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('614c03ef-af0f-5843-b357-e726b114cd36', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 28 year old woman is in recovery after a laparoscopic cholecystectomy under general anaesthetic. Twenty minutes after arriving she has nausea and has vomited twice. She has a history of motion sickness and is a non-smoker. She received ondansetron at the end of surgery. Her observations are normal. What is the SINGLE most appropriate antiemetic?', 'PONV risk factors (Apfel score): female, non-smoker, history of PONV or motion sickness, post-operative opioids. Prophylaxis with dexamethasone and ondansetron. Rescue therapy should use a different class. Avoid metoclopramide in suspected bowel obstruction.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('571180b0-d200-58da-9ed2-663f8dd43420', '614c03ef-af0f-5843-b357-e726b114cd36', 'A', 'A drug from a different class (e.g. cyclizine), as a repeat of ondansetron within 6 hours is unlikely to help', true, 0),
  ('cac96901-f9c4-5a45-a533-4806109cbf8a', '614c03ef-af0f-5843-b357-e726b114cd36', 'B', 'IV morphine', false, 1),
  ('c54d9cba-5c3d-5ead-b179-66d87076c012', '614c03ef-af0f-5843-b357-e726b114cd36', 'C', 'Metoclopramide is contraindicated in all', false, 2),
  ('dd6db931-db4c-59ff-9d48-1d7a4b2f4e1c', '614c03ef-af0f-5843-b357-e726b114cd36', 'D', 'Repeat ondansetron', false, 3),
  ('3da6d220-f797-5393-94d7-fc9ecd4467e8', '614c03ef-af0f-5843-b357-e726b114cd36', 'E', 'No treatment; reassure only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('182b6607-054e-5138-94c0-831312513632', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 62 year old woman of Chinese origin presents to the emergency department with severe pain in her right eye and headache that started this evening while she was reading in dim light. She is vomiting. She sees halos around lights. Her right eye is red with a hazy cornea, and the pupil is fixed and mid-dilated. The eye feels hard on palpation. Visual acuity is 6/60. What is the SINGLE most appropriate immediate management?', 'Acute angle-closure glaucoma: risk factors include female sex, older age, hypermetropia and East Asian ethnicity. Dim light and mydriasis precipitate it. Lower IOP urgently, then laser peripheral iridotomy for both eyes.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('50b67b48-c111-5e1a-ba79-379507b1cb64', '182b6607-054e-5138-94c0-831312513632', 'A', 'Urgent same-day ophthalmology, lie her flat, and give IV acetazolamide with topical pilocarpine, beta-blocker and steroid drops', true, 0),
  ('ce8dd226-d4c1-58f8-8d11-196147a7ed81', '182b6607-054e-5138-94c0-831312513632', 'B', 'Review tomorrow in clinic', false, 1),
  ('20da542d-167f-5d85-8041-e12a6bb2f0a9', '182b6607-054e-5138-94c0-831312513632', 'C', 'Oral NSAIDs only', false, 2),
  ('80ac7958-509e-5393-bee6-ebf45e7c3c97', '182b6607-054e-5138-94c0-831312513632', 'D', 'Dilating eye drops', false, 3),
  ('aa321747-65f1-5c27-b5aa-0f8f6e3be477', '182b6607-054e-5138-94c0-831312513632', 'E', 'Antibiotic eye drops', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('048778c5-914a-543d-8caf-7774d585f2a4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 78 year old woman presents with sudden loss of vision in her right eye this morning. For 3 weeks she has had a new headache, pain in her jaw when chewing and tenderness when combing her hair. She has also had shoulder stiffness. Visual acuity is counting fingers in the right eye. Fundoscopy shows a pale, swollen optic disc. ESR is 98 mm/hour. What is the SINGLE most appropriate immediate management?', 'GCA with visual loss: arteritic anterior ischaemic optic neuropathy. Give steroids immediately; biopsy within 2 weeks of starting steroids is still diagnostic. Protect the other eye. Bone protection, PPI and consider tocilizumab for relapsing disease.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('462af1c7-dd69-5e6c-934f-14604c74221b', '048778c5-914a-543d-8caf-7774d585f2a4', 'A', 'Refer routinely to rheumatology', false, 0),
  ('2c12bebb-e402-5022-a084-ddcb626241f7', '048778c5-914a-543d-8caf-7774d585f2a4', 'B', 'Aspirin only', false, 1),
  ('cebddb75-4061-5561-80ca-349fd83f2d9c', '048778c5-914a-543d-8caf-7774d585f2a4', 'C', 'IV methylprednisolone (visual loss), then high-dose oral prednisolone, with urgent ophthalmology and temporal artery biopsy or ultrasound', true, 2),
  ('9a8b33a8-6418-595b-8f50-05cd1d9880bb', '048778c5-914a-543d-8caf-7774d585f2a4', 'D', 'Oral prednisolone 15 mg', false, 3),
  ('c2492113-38d2-59b3-987f-9c46b758e7e3', '048778c5-914a-543d-8caf-7774d585f2a4', 'E', 'Wait for temporal artery biopsy before steroids', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('35d2f47f-82ce-535f-b1b5-459c9a4794f3', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 44 year old man with poorly controlled type 1 diabetes has a sudden shower of floaters and loss of vision in his left eye. He has had laser treatment in the past. Visual acuity is hand movements in the left eye. Fundus view is obscured with no red reflex. Ultrasound of the eye shows the retina is attached. What is the SINGLE most likely diagnosis?', 'Vitreous haemorrhage from new vessels causes sudden floaters or vision loss with a poor fundus view. Ultrasound excludes detachment. Treatment: observation, anti-VEGF, laser and vitrectomy for non-clearing haemorrhage.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('21279411-b3da-55b7-94e9-37d565fb3873', '35d2f47f-82ce-535f-b1b5-459c9a4794f3', 'A', 'Acute angle-closure glaucoma', false, 0),
  ('1936e618-4b39-5d74-addb-e0f783868e60', '35d2f47f-82ce-535f-b1b5-459c9a4794f3', 'B', 'Central retinal artery occlusion', false, 1),
  ('8661e29d-4150-5696-9632-b0f9f7a75ce0', '35d2f47f-82ce-535f-b1b5-459c9a4794f3', 'C', 'Cataract', false, 2),
  ('0917a8a6-8766-556e-a9a1-1a1ce36cec89', '35d2f47f-82ce-535f-b1b5-459c9a4794f3', 'D', 'Retinal detachment', false, 3),
  ('b58d37e9-2fdb-53a6-851b-5fb93e1eca10', '35d2f47f-82ce-535f-b1b5-459c9a4794f3', 'E', 'Vitreous haemorrhage from proliferative diabetic retinopathy', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7193dcc4-cf45-552c-b644-a9336639b50c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 68 year old man with type 2 diabetes has had severe left ear pain for 3 weeks, worse at night, with discharge. He has been using antibiotic ear drops without improvement. Otoscopy shows granulation tissue on the floor of the ear canal. He now has weakness on the left side of his face. CRP is 70 mg/L. What is the SINGLE most likely diagnosis?', 'Necrotising otitis externa is a skull base osteomyelitis, usually caused by Pseudomonas, in older people with diabetes or immunosuppression. Cranial nerve palsies (VII first) indicate spread. CT or MRI; prolonged IV anti-pseudomonal antibiotics; ENT referral.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('be02c891-ef69-5d00-ac34-af6205154ed6', '7193dcc4-cf45-552c-b644-a9336639b50c', 'A', 'Necrotising (malignant) otitis externa', true, 0),
  ('b4a52e2f-1710-54a4-a09f-1169aab27546', '7193dcc4-cf45-552c-b644-a9336639b50c', 'B', 'Otitis media', false, 1),
  ('14125081-7125-52bb-b079-b8c39f04a018', '7193dcc4-cf45-552c-b644-a9336639b50c', 'C', 'Cholesteatoma', false, 2),
  ('36af4701-161e-53c3-8a4a-80b0a7cd7e58', '7193dcc4-cf45-552c-b644-a9336639b50c', 'D', 'Ramsay Hunt syndrome', false, 3),
  ('e6498814-60c7-585a-95e0-cae5190f7f36', '7193dcc4-cf45-552c-b644-a9336639b50c', 'E', 'Bell''s palsy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ac4ba741-573a-53da-9e82-c937a0bc4a94', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 26 year old man presents with a severe sore throat for 4 days, now worse on the left side. He has difficulty swallowing his saliva and can only open his mouth a little. His voice sounds muffled. Temperature 38.8 °C. The uvula is pushed to the right and there is a bulge above the left tonsil. What is the SINGLE most appropriate management?', 'Peritonsillar abscess (quinsy): trismus, uvula deviation, ''hot potato'' voice. Same-day ENT referral. Interval tonsillectomy is considered for recurrent quinsy or recurrent tonsillitis.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7bfa19dd-5325-545c-9027-883d39c72b00', 'ac4ba741-573a-53da-9e82-c937a0bc4a94', 'A', 'Needle aspiration or incision and drainage, with IV antibiotics (benzylpenicillin and metronidazole), steroids and analgesia', true, 0),
  ('6ba29f1c-6551-5187-95bb-bcff0ea5a51b', 'ac4ba741-573a-53da-9e82-c937a0bc4a94', 'B', 'Watch and wait', false, 1),
  ('0c951085-b5a3-563a-8a3d-f311feafe840', 'ac4ba741-573a-53da-9e82-c937a0bc4a94', 'C', 'Oral steroids only', false, 2),
  ('71223588-ce72-568b-9445-5679f46309ff', 'ac4ba741-573a-53da-9e82-c937a0bc4a94', 'D', 'Oral penicillin and discharge', false, 3),
  ('487ee604-192a-5522-ba93-c94dd8df9cf1', 'ac4ba741-573a-53da-9e82-c937a0bc4a94', 'E', 'Tonsillectomy immediately in all', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('014411e5-33bf-55a9-8569-fa3255a183bb', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 70 year old man is admitted with heavy bleeding from his nose for 1 hour that has not stopped despite pinching the soft part of his nose for 20 minutes. He takes warfarin for AF; his INR is 4.2. HR 108 bpm, BP 150/88 mmHg. Examination shows no visible bleeding point at the front of the nose. Blood is running down the back of his throat. What is the SINGLE most appropriate next step?', 'Epistaxis: first aid (lean forward, pinch the soft part of the nose for 10-15 minutes), cautery if a bleeding point is visible, otherwise anterior packing. Posterior bleeds may need posterior packing or sphenopalatine artery ligation. Reverse excess anticoagulation with vitamin K. Tranexamic acid may help.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a8bd1fd2-6638-529e-806e-3021a3571716', '014411e5-33bf-55a9-8569-fa3255a183bb', 'A', 'Silver nitrate cautery of a hidden posterior bleed', false, 0),
  ('ad22b03c-526a-5ac0-885f-1f4c1be7149b', '014411e5-33bf-55a9-8569-fa3255a183bb', 'B', 'Stop warfarin permanently', false, 1),
  ('d7b379ab-f8ff-5143-9298-5bc793fdbe89', '014411e5-33bf-55a9-8569-fa3255a183bb', 'C', 'Discharge with advice', false, 2),
  ('a5934ce0-e7ad-5c97-b149-e75475ac3eaa', '014411e5-33bf-55a9-8569-fa3255a183bb', 'D', 'Insert anterior nasal packing (e.g. nasal tampon), resuscitate, and correct anticoagulation with ENT input', true, 3),
  ('f183d1be-637c-57c5-b2cd-0d07b3b45a6e', '014411e5-33bf-55a9-8569-fa3255a183bb', 'E', 'Tilt head back and continue pinching', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b9a4a8e8-8ff6-5b5e-91c7-c46e1471ec5c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 72 year old woman has had itchy, tense blisters on her thighs, abdomen and arms for 3 weeks. Some blisters are filled with blood. Her mouth is not affected. Nikolsky''s sign is negative. She has dementia and takes furosemide. Skin biopsy with direct immunofluorescence shows linear IgG and C3 at the dermo-epidermal junction. What is the SINGLE most appropriate treatment?', 'Bullous pemphigoid occurs in older people, with tense subepidermal blisters and antibodies to BP180 and BP230. Drugs (furosemide, gliptins) can trigger it. Pemphigus vulgaris has flaccid, fragile intraepidermal blisters with mouth involvement and positive Nikolsky''s sign.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ee95edfe-e001-5529-ba17-307894f8abbc', 'b9a4a8e8-8ff6-5b5e-91c7-c46e1471ec5c', 'A', 'Topical antifungal', false, 0),
  ('7517230b-9869-5c32-9f8e-2460df5990c2', 'b9a4a8e8-8ff6-5b5e-91c7-c46e1471ec5c', 'B', 'Aciclovir', false, 1),
  ('6614af77-c5a4-549d-b247-29f69520f23d', 'b9a4a8e8-8ff6-5b5e-91c7-c46e1471ec5c', 'C', 'Potent topical steroids (e.g. clobetasol) or oral prednisolone, and dermatology referral', true, 2),
  ('ca466386-57bd-5e0a-a6ec-4fc75213e712', 'b9a4a8e8-8ff6-5b5e-91c7-c46e1471ec5c', 'D', 'Emollients alone', false, 3),
  ('e0eac770-4c8e-5dad-91d2-329a135b0704', 'b9a4a8e8-8ff6-5b5e-91c7-c46e1471ec5c', 'E', 'Oral antibiotics only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3ed149fe-0397-5f1f-a821-0cb6017b78cb', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 4 year old child with eczema develops a rapidly spreading painful rash over 24 hours. There are clusters of punched-out erosions with crusts over his face and neck, and he has a fever of 38.5 °C. He is lethargic. He was using his usual emollient and topical steroid. What is the SINGLE most appropriate management?', 'Eczema herpeticum is a widespread HSV infection on eczematous skin. It can be life-threatening. Treat with aciclovir (IV if unwell). Refer to ophthalmology if around the eyes.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('24836a0f-4f1c-5316-8078-c5aad4a86ec3', '3ed149fe-0397-5f1f-a821-0cb6017b78cb', 'A', 'Increase topical steroid', false, 0),
  ('da23159e-4dd3-552c-ac38-a09968985165', '3ed149fe-0397-5f1f-a821-0cb6017b78cb', 'B', 'Topical antifungal', false, 1),
  ('c1f5a408-c5ab-5820-9003-e75547a30838', '3ed149fe-0397-5f1f-a821-0cb6017b78cb', 'C', 'Oral flucloxacillin only', false, 2),
  ('10a1a63b-ed9a-558d-950c-e4007797886a', '3ed149fe-0397-5f1f-a821-0cb6017b78cb', 'D', 'Emollient only', false, 3),
  ('f1673b1d-ee43-5004-b951-8042c145350c', '3ed149fe-0397-5f1f-a821-0cb6017b78cb', 'E', 'Same-day referral and treatment with aciclovir (eczema herpeticum)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('255b3f7f-68ed-5eac-9c34-f038c29c26e8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 58 year old man has had a pigmented lesion on his back for many years. His wife noticed it has changed in the last 3 months. It is 9 mm with irregular, notched edges, three different colours and has started to itch and bleed. What is the SINGLE most appropriate management?', 'The weighted 7-point checklist: major features (change in size, shape, colour) score 2; minor (diameter 7 mm or more, inflammation, oozing, change in sensation) score 1. A score of 3 or more warrants referral. Melanoma prognosis depends on Breslow thickness.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a4348c89-b8d2-5105-bab4-c8b440b980cf', '255b3f7f-68ed-5eac-9c34-f038c29c26e8', 'A', 'Topical steroid', false, 0),
  ('6a532a29-8402-5f40-88d9-9433493cab3b', '255b3f7f-68ed-5eac-9c34-f038c29c26e8', 'B', 'Cryotherapy', false, 1),
  ('63474029-68ce-5b32-92f9-58ce472cbf7b', '255b3f7f-68ed-5eac-9c34-f038c29c26e8', 'C', 'Two-week-wait suspected skin cancer referral (do not remove in primary care)', true, 2),
  ('69c42e60-e959-5d53-8a26-418c51e0a001', '255b3f7f-68ed-5eac-9c34-f038c29c26e8', 'D', 'Reassure and review in 6 months', false, 3),
  ('a55d8cd3-6fdf-5b41-b45c-7e489f030209', '255b3f7f-68ed-5eac-9c34-f038c29c26e8', 'E', 'Shave biopsy in the GP surgery', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ecb60c25-b0fd-5669-a1b0-242d4d27dd21', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 56 year old man presents with a red, hot, swollen right knee for 2 days. He cannot weight-bear. He had a hip replacement 4 years ago. Temperature 38.9 °C. HR 108 bpm. WCC 16 x 10^9/L and CRP 210 mg/L. He has a history of gout. Joint aspiration shows turbid fluid. What is the SINGLE most appropriate management?', 'Septic arthritis must be excluded in any hot swollen joint, even with known gout (both can coexist). Aspirate before antibiotics if possible. S. aureus is the commonest organism. Gonococcus in young, sexually active people. Joint washout. Never inject steroids into a possibly infected joint.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cbc45176-12ad-5a1d-bb2c-3e162855a16b', 'ecb60c25-b0fd-5669-a1b0-242d4d27dd21', 'A', 'Oral NSAIDs and discharge', false, 0),
  ('946a0b50-6a77-50fe-af00-c38e087eb1b7', 'ecb60c25-b0fd-5669-a1b0-242d4d27dd21', 'B', 'Send synovial fluid for Gram stain, culture and crystals, take blood cultures, then start IV flucloxacillin (local policy), with orthopaedic referral for washout', true, 1),
  ('e3b65330-0d17-5ffa-a094-a83a9b6f01a8', 'ecb60c25-b0fd-5669-a1b0-242d4d27dd21', 'C', 'Intra-articular steroid injection', false, 2),
  ('42e470fb-474e-5726-8b98-429810df9b13', 'ecb60c25-b0fd-5669-a1b0-242d4d27dd21', 'D', 'Treat as gout with colchicine only', false, 3),
  ('4644dd39-bbb4-5100-8c4f-9d79740c9928', 'ecb60c25-b0fd-5669-a1b0-242d4d27dd21', 'E', 'Wait for culture results before antibiotics', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('502d2f9a-03bd-57ef-8049-3eb146bc6a9f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 34 year old woman presents with a 3-month history of pain and swelling in the small joints of both hands and both feet. Morning stiffness lasts 2 hours. She is a smoker. Examination shows swelling of the MCP and PIP joints bilaterally. Rheumatoid factor is positive. Anti-CCP is strongly positive. CRP is 34 mg/L. X-rays of the hands show periarticular erosions. What is the SINGLE most appropriate first-line treatment?', 'NICE NG100: start conventional DMARD monotherapy (methotrexate, leflunomide or sulfasalazine) ideally within 3 months of symptom onset, with short-term steroid bridging. Biologics for persistent disease activity (DAS28 over 5.1) after two DMARDs. Methotrexate: check FBC, LFTs, renal function; avoid in pregnancy; avoid trimethoprim.', null, true, true, jsonb_build_object('source', 'plab1-xlsx-v7', 'guidelines_text', 'NICE NG100')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('839101f3-b50f-5dc5-9563-4adb3baa0240', '502d2f9a-03bd-57ef-8049-3eb146bc6a9f', 'A', 'Methotrexate (with folic acid), with bridging steroids, started promptly', true, 0),
  ('c048523f-a3ce-5e98-b83f-9d41acf32d77', '502d2f9a-03bd-57ef-8049-3eb146bc6a9f', 'B', 'Biologic (anti-TNF) first-line', false, 1),
  ('35ed1be4-6a03-5d16-bd0b-78bb54434306', '502d2f9a-03bd-57ef-8049-3eb146bc6a9f', 'C', 'NSAIDs alone', false, 2),
  ('41a15f8e-ddcd-55ae-833a-3e2c66da5618', '502d2f9a-03bd-57ef-8049-3eb146bc6a9f', 'D', 'Hydroxychloroquine alone in all cases', false, 3),
  ('c77ae3f8-1f06-5f8e-a763-6f768d619ac1', '502d2f9a-03bd-57ef-8049-3eb146bc6a9f', 'E', 'Gold injections', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('dd93d778-d649-549f-81b7-dbab407a486b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 24 year old man has had low back pain and stiffness for 1 year, worse in the morning and better with exercise. He wakes in the second half of the night with pain. He had a red, painful eye last year. Schober''s test is reduced. CRP is raised. X-ray of the pelvis shows bilateral sacroiliitis. What is the SINGLE most appropriate first-line treatment?', 'Axial spondyloarthritis (ankylosing spondylitis): inflammatory back pain in young men, HLA-B27, anterior uveitis, enthesitis. MRI detects early sacroiliitis. NSAIDs and exercise first-line, then anti-TNF or IL-17 inhibitors. Methotrexate is not effective for axial disease. Complications: apical fibrosis, aortic regurgitation, vertebral fracture.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5fa8f7b7-e845-5554-8191-b21bbd4b6c9e', 'dd93d778-d649-549f-81b7-dbab407a486b', 'A', 'Opioids only', false, 0),
  ('1b9b475c-40e7-5654-a2d3-02c25f44818e', 'dd93d778-d649-549f-81b7-dbab407a486b', 'B', 'Methotrexate', false, 1),
  ('90c2d1a6-f51d-54b9-ab12-3d5af81f3613', 'dd93d778-d649-549f-81b7-dbab407a486b', 'C', 'NSAIDs and physiotherapy (exercise)', true, 2),
  ('1d290a9c-fce8-52cd-bd9e-ac39e6bf277f', 'dd93d778-d649-549f-81b7-dbab407a486b', 'D', 'Long-term oral steroids', false, 3),
  ('8f8b52ca-07e9-525a-b354-60e244d3bb8e', 'dd93d778-d649-549f-81b7-dbab407a486b', 'E', 'Bed rest', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3bdc52b6-4f2f-5331-8ad2-5e01ec8435dd', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 72 year old woman fell from standing onto her outstretched right hand. She has a painful, deformed wrist. X-ray shows a fracture of the distal radius with dorsal displacement and angulation (''dinner fork'' deformity). She is otherwise fit and lives independently. Median nerve function is normal. What is the SINGLE most important additional step after treating the fracture?', 'Colles'' fractures in older people are fragility fractures. Fracture liaison services assess for osteoporosis. Management: closed reduction and cast, or fixation if unstable. Complications: median nerve injury, malunion, complex regional pain syndrome and EPL rupture.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('65f14ab0-771c-5b50-9ea2-604c9df9cc0b', '3bdc52b6-4f2f-5331-8ad2-5e01ec8435dd', 'A', 'Long-term calcium only without assessment', false, 0),
  ('a3c648db-4ee7-53c3-8399-494443ac427c', '3bdc52b6-4f2f-5331-8ad2-5e01ec8435dd', 'B', 'No further action', false, 1),
  ('7b2c835a-d2cc-5a46-9bc0-98b81c4cd985', '3bdc52b6-4f2f-5331-8ad2-5e01ec8435dd', 'C', 'X-ray the other wrist', false, 2),
  ('1ac6ac09-4d04-5be5-93f3-ecdd099178e8', '3bdc52b6-4f2f-5331-8ad2-5e01ec8435dd', 'D', 'Osteoporosis assessment (FRAX and DEXA) and bone protection as appropriate', true, 3),
  ('fb240e57-f668-5f14-97d4-8222c33faa3f', '3bdc52b6-4f2f-5331-8ad2-5e01ec8435dd', 'E', 'Refer to physiotherapy only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('514bbbca-5091-5cd4-9781-85e9be6046ad', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 58 year old woman had a wrist fracture treated in a cast. Eight weeks later she has burning pain out of proportion to the injury, swelling, shiny skin, colour change, sweating and stiffness of the hand. Touch is very painful. X-ray shows patchy osteopenia. What is the SINGLE most likely diagnosis?', 'CRPS (Budapest criteria) includes sensory, vasomotor, sudomotor and motor/trophic changes. Management: early physiotherapy and occupational therapy, pain management (neuropathic agents), and psychological support. Early mobilisation after fractures may reduce risk.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cc937d37-4759-5281-ae73-8bc609468137', '514bbbca-5091-5cd4-9781-85e9be6046ad', 'A', 'Infection', false, 0),
  ('ab0e2861-fdc3-5766-beb4-85631ab2faeb', '514bbbca-5091-5cd4-9781-85e9be6046ad', 'B', 'DVT of the arm', false, 1),
  ('5d601531-a5a7-57c9-a16b-ecd43dcdab75', '514bbbca-5091-5cd4-9781-85e9be6046ad', 'C', 'Carpal tunnel syndrome', false, 2),
  ('12a9a526-10b8-5e91-bf63-edec9cc4bc65', '514bbbca-5091-5cd4-9781-85e9be6046ad', 'D', 'Malunion', false, 3),
  ('4735b63f-0f6b-59ba-856e-8c661fa59fc1', '514bbbca-5091-5cd4-9781-85e9be6046ad', 'E', 'Complex regional pain syndrome', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('28885910-fbd5-5d10-8fa6-0b3ba9fe008e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 52 year old man with a learning disability and an IQ of 55 is admitted with a bowel obstruction that needs surgery. He becomes distressed when the operation is discussed. The surgical team has explained the risks and benefits using simple words and pictures with his carer present. He understands that he has a blockage, but cannot explain or weigh up what will happen with or without surgery. He has no LPA or advance decision. He has no family. What is the SINGLE most appropriate action?', 'Mental Capacity Act 2005: capacity is decision-specific (understand, retain, weigh up, communicate). If he lacks capacity and has nobody to consult, an IMCA must be instructed for serious medical treatment (unless it is an emergency). Decisions are made in his best interests. Carers cannot consent on his behalf without legal authority.', null, true, true, jsonb_build_object('source', 'plab1-xlsx-v7', 'guidelines_text', 'Mental Capacity Act')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bb6f595d-7304-5e0f-92d7-f79480ef1ec9', '28885910-fbd5-5d10-8fa6-0b3ba9fe008e', 'A', 'Ask his carer to consent', false, 0),
  ('9bc5a4fc-d7a9-50d1-8ff6-2140c0cbf514', '28885910-fbd5-5d10-8fa6-0b3ba9fe008e', 'B', 'Wait until he regains capacity', false, 1),
  ('9affc406-4510-5759-bfc6-7e9a95f82c4c', '28885910-fbd5-5d10-8fa6-0b3ba9fe008e', 'C', 'Apply to court in all cases before any treatment', false, 2),
  ('0a7cb824-0a37-5343-a2c3-c7bbde712144', '28885910-fbd5-5d10-8fa6-0b3ba9fe008e', 'D', 'Assess as lacking capacity for this decision, appoint an IMCA if time allows, and proceed in his best interests', true, 3),
  ('73b6ea1b-c836-5f30-876f-714587cfb770', '28885910-fbd5-5d10-8fa6-0b3ba9fe008e', 'E', 'Proceed only if he signs the form', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2e95497d-c970-5d3c-8526-9b356edda261', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 15 year old girl attends the GP alone, asking for the contraceptive pill. She has a 17 year old boyfriend and they have been having sex for 2 months. She does not want her parents to know. She understands the benefits and risks and will continue to have sex whether or not she gets contraception. There are no concerns about exploitation or abuse. What is the SINGLE most appropriate action?', 'Fraser guidelines apply to contraception for under-16s: she understands, cannot be persuaded to tell parents, will have sex anyway, her health would suffer without it, and it is in her best interests. Assess for child sexual exploitation; under 13 is always a safeguarding issue.', null, true, true, jsonb_build_object('source', 'plab1-xlsx-v7', 'guidelines_text', 'Fraser guidelines')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bbcc8ae3-9a8d-5f2d-a94a-43de5a7d9633', '2e95497d-c970-5d3c-8526-9b356edda261', 'A', 'Prescribe the pill after encouraging her to involve her parents, as she meets the Fraser guidelines', true, 0),
  ('7ba90590-1812-597b-9f7c-99f105ef885c', '2e95497d-c970-5d3c-8526-9b356edda261', 'B', 'Refuse until she is 16', false, 1),
  ('89f3855f-43cc-5930-8ded-87f557b02686', '2e95497d-c970-5d3c-8526-9b356edda261', 'C', 'Call her parents', false, 2),
  ('c2df09fa-aee2-5180-95a5-8b9b42823640', '2e95497d-c970-5d3c-8526-9b356edda261', 'D', 'Prescribe only if her boyfriend attends', false, 3),
  ('30d61444-3f31-584c-8f32-615501f17909', '2e95497d-c970-5d3c-8526-9b356edda261', 'E', 'Inform the police', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('64680c32-6ff9-58f2-9b5f-f3698602b72f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000013', 'sba', 'A 78 year old man has advanced lung cancer and has been told he has weeks to live. His daughter asks the doctor not to tell him about the scan results, because ''he would give up''. The patient has capacity. When the doctor visits, he asks directly what the scan showed. What is the SINGLE most appropriate action?', 'GMC: patients with capacity have a right to information about their condition. Relatives cannot veto information. Doctors should not withhold information unless giving it would cause serious harm (not just upset). Explore his preferences and support the family.', null, true, true, jsonb_build_object('source', 'plab1-xlsx-v7', 'guidelines_text', 'GMC')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0d2d6f47-921a-5a16-aeaa-ca56c350a3d3', '64680c32-6ff9-58f2-9b5f-f3698602b72f', 'A', 'Tell him everything in full detail immediately without checking what he wants', false, 0),
  ('f3deb89f-0cd6-5df9-a4aa-70d7ede3f516', '64680c32-6ff9-58f2-9b5f-f3698602b72f', 'B', 'Explore what he wants to know and give him honest information at a pace he chooses', true, 1),
  ('8d2c88da-33c6-5f57-af7b-ba67fb2d0a5c', '64680c32-6ff9-58f2-9b5f-f3698602b72f', 'C', 'Lie to him to protect him', false, 2),
  ('0746630e-c19e-5d77-9868-df3113a1ff5d', '64680c32-6ff9-58f2-9b5f-f3698602b72f', 'D', 'Follow the daughter''s wishes and withhold the result', false, 3),
  ('66cd4094-cec1-5c61-9b39-383fda4d1963', '64680c32-6ff9-58f2-9b5f-f3698602b72f', 'E', 'Refer him to another doctor', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('acb1e117-a5fe-524a-bdf5-fe2004c1a980', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 45 year old woman sees her GP with tiredness, low mood, weight gain, constipation and feeling cold for 3 months. Her periods have become heavier. She has dry skin and a slow pulse. Blood tests show TSH 18 mU/L and free T4 7 pmol/L. Thyroid peroxidase antibodies are strongly positive. She has no cardiac history. What is the SINGLE most appropriate management?', 'Primary hypothyroidism (Hashimoto''s). Younger patients without heart disease can start the full dose; in older people or those with ischaemic heart disease, start low (25 micrograms) and titrate. Take on an empty stomach, separate from iron and calcium. Increase dose in pregnancy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e3e822c0-e064-5585-b9c2-80911d5011f0', 'acb1e117-a5fe-524a-bdf5-fe2004c1a980', 'A', 'Start levothyroxine at full replacement dose (around 1.6 micrograms/kg/day) and recheck TFTs in 6-8 weeks', true, 0),
  ('6874b06b-6d6e-56ce-a7ea-40c83d082790', 'acb1e117-a5fe-524a-bdf5-fe2004c1a980', 'B', 'Start levothyroxine 25 micrograms in all patients', false, 1),
  ('4f1fd368-e240-5e01-9c7f-fddad0533308', 'acb1e117-a5fe-524a-bdf5-fe2004c1a980', 'C', 'Carbimazole', false, 2),
  ('68798d2b-a755-5350-b0fd-bc3b0ca11e4d', 'acb1e117-a5fe-524a-bdf5-fe2004c1a980', 'D', 'Radioactive iodine', false, 3),
  ('2d8ce9f9-40aa-57a4-9b11-9c8414f58532', 'acb1e117-a5fe-524a-bdf5-fe2004c1a980', 'E', 'Repeat TFTs in 6 months with no treatment', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d550da24-c7f3-54ec-81a3-6a67ea2fce16', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 58 year old man sees his GP for a medication review. He has type 2 diabetes, hypertension and a BMI of 34. He smokes 20 cigarettes a day and drinks 30 units of alcohol a week. He says he wants to cut down on smoking but not yet stop. What is the SINGLE most appropriate approach?', '''Very brief advice'' (Ask, Advise, Act). Combining behavioural support and pharmacotherapy (varenicline, combination NRT, or e-cigarettes) is most effective. Motivational interviewing helps explore ambivalence. Alcohol: use AUDIT-C and brief interventions.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('3ec289c7-b602-5092-ac40-5c18301b0244', 'd550da24-c7f3-54ec-81a3-6a67ea2fce16', 'A', 'Tell him he must stop immediately or will be removed from the practice list', false, 0),
  ('c1901a35-5aae-527c-a0f7-0f4ba5e35725', 'd550da24-c7f3-54ec-81a3-6a67ea2fce16', 'B', 'Ignore smoking and focus on diabetes only', false, 1),
  ('a244cdc4-13f2-5bbc-b966-2adafdd07d97', 'd550da24-c7f3-54ec-81a3-6a67ea2fce16', 'C', 'Advise e-cigarettes are as harmful as tobacco', false, 2),
  ('1fb90922-7098-5432-9bb2-e4f19c24e494', 'd550da24-c7f3-54ec-81a3-6a67ea2fce16', 'D', 'Use brief intervention and motivational interviewing to explore his ambivalence and offer referral to stop smoking services with pharmacotherapy (varenicline or NRT)', true, 3),
  ('be760304-d138-571d-961d-efd44ea0e100', 'd550da24-c7f3-54ec-81a3-6a67ea2fce16', 'E', 'Prescribe varenicline without discussion', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('555acb6f-ee40-5ece-9c3a-199d205508f3', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 32 year old woman sees her GP with episodes of a racing heart, sweating, shaking and fear that she is going to die, lasting about 10 minutes. They happen without warning several times a week. She now avoids going out alone. ECG, thyroid function and glucose are normal. What is the SINGLE most appropriate first-line treatment?', 'NICE CG113: panic disorder is treated with CBT; SSRIs (licensed for panic disorder) if needed. Avoid benzodiazepines (dependence). Exclude medical causes (thyroid, arrhythmia, phaeochromocytoma).', null, true, true, jsonb_build_object('source', 'plab1-xlsx-v7', 'guidelines_text', 'NICE CG113')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('619ece7e-bd62-5eb4-bba7-e93503fb223b', '555acb6f-ee40-5ece-9c3a-199d205508f3', 'A', 'Reassurance only', false, 0),
  ('1d266fbb-46cb-596e-9a15-d114b4e10cec', '555acb6f-ee40-5ece-9c3a-199d205508f3', 'B', 'Antipsychotics', false, 1),
  ('617fcafa-e9f3-55fd-9bbf-7903ad64eb3d', '555acb6f-ee40-5ece-9c3a-199d205508f3', 'C', 'Benzodiazepines long-term', false, 2),
  ('5e9ebbb3-5344-57ae-9dbf-bf593e4aac80', '555acb6f-ee40-5ece-9c3a-199d205508f3', 'D', 'CBT (individual or guided self-help) for panic disorder, with an SSRI if needed', true, 3),
  ('4a27bcef-3341-535a-bc42-31bc248d8e3a', '555acb6f-ee40-5ece-9c3a-199d205508f3', 'E', 'Beta-blockers alone', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('af156821-398a-5ad2-b79d-d8d8a5f56794', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 62 year old man has been in ICU for 4 days with pneumonia and septic shock. He is ventilated and on noradrenaline 0.3 micrograms/kg/min despite adequate fluid resuscitation. His MAP is 62 mmHg. Lactate is 3.8 mmol/L. Blood cultures grew Streptococcus pneumoniae and he is on appropriate antibiotics. What is the SINGLE most appropriate additional treatment?', 'Surviving Sepsis: target MAP of 65 mmHg. Noradrenaline first-line, then add vasopressin. IV hydrocortisone for persistent vasopressor requirement. Avoid excessive fluids. Consider source control.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1b432867-57fc-515a-8e69-016091cf7cc7', 'af156821-398a-5ad2-b79d-d8d8a5f56794', 'A', 'Add vasopressin and consider IV hydrocortisone (refractory septic shock)', true, 0),
  ('1764fbbe-d405-5d97-a9ab-ec4ed45abcb2', 'af156821-398a-5ad2-b79d-d8d8a5f56794', 'B', 'Change antibiotics without culture guidance', false, 1),
  ('1d6b1a53-5aad-5a8b-be6e-321a0bf68f89', 'af156821-398a-5ad2-b79d-d8d8a5f56794', 'C', 'Stop noradrenaline', false, 2),
  ('d7e1d36a-bc2e-5470-945a-0f2438fef9ff', 'af156821-398a-5ad2-b79d-d8d8a5f56794', 'D', 'Give 4 L of further fluid', false, 3),
  ('68482250-1786-5109-9e37-a522cfc6d043', 'af156821-398a-5ad2-b79d-d8d8a5f56794', 'E', 'Start beta-blocker', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7d58e35a-2c6a-5574-be76-531eda27336b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 48 year old man is in ICU after a cardiac arrest from VF. He had ROSC after 15 minutes. He is ventilated and sedated. His temperature is 38.2 °C. What is the SINGLE most appropriate temperature management?', 'Post-cardiac arrest care (ERC/ESICM 2021): targeted temperature management to prevent fever, avoid hypoxia and hyperoxia, maintain MAP over 65, coronary angiography if STEMI. Prognostication is delayed until at least 72 hours.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9105f13e-b0ae-5828-9b56-77c4a4f07d1d', '7d58e35a-2c6a-5574-be76-531eda27336b', 'A', 'Rapid cooling to 30 °C', false, 0),
  ('925a9443-65a2-50ef-b5b2-d1d7482dfff0', '7d58e35a-2c6a-5574-be76-531eda27336b', 'B', 'Actively prevent fever (keep temperature at 37.5 °C or below) for at least 72 hours', true, 1),
  ('62b2c36c-9d52-5034-80fe-d52520901ca0', '7d58e35a-2c6a-5574-be76-531eda27336b', 'C', 'Allow fever to develop', false, 2),
  ('a53efa85-6e3a-5086-96c1-4c7d6e96542a', '7d58e35a-2c6a-5574-be76-531eda27336b', 'D', 'No temperature monitoring', false, 3),
  ('e593f056-b8d2-51cd-8608-7b7295e900f6', '7d58e35a-2c6a-5574-be76-531eda27336b', 'E', 'Warm to 39 °C', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9c23ec57-1bf3-58bc-bf77-1921df3eb266', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 40 year old woman is in ICU after major trauma. On day 3 she develops worsening oxygenation. Her PaO2/FiO2 is 150 mmHg on PEEP of 10 cmH2O. CXR shows bilateral infiltrates. Echocardiogram shows normal left ventricular function. What is the SINGLE most likely diagnosis?', 'Berlin ARDS criteria: onset within 1 week, bilateral opacities, not explained by heart failure, and PaO2/FiO2 (on PEEP of 5 or more): mild 200-300, moderate 100-200, severe under 100. Causes: sepsis, pneumonia, trauma, pancreatitis, transfusion. Lung-protective ventilation, conservative fluids, proning in severe cases.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('483d97c9-1bdb-521e-944a-180ad395bdd0', '9c23ec57-1bf3-58bc-bf77-1921df3eb266', 'A', 'Pneumothorax', false, 0),
  ('90572ba3-b5cf-5ded-97bd-473a5089cae8', '9c23ec57-1bf3-58bc-bf77-1921df3eb266', 'B', 'Pleural effusion', false, 1),
  ('a3febc03-a283-5c0a-b213-91d5d330e279', '9c23ec57-1bf3-58bc-bf77-1921df3eb266', 'C', 'Moderate acute respiratory distress syndrome', true, 2),
  ('5338981f-a5f5-5b30-83de-471f2bda6d66', '9c23ec57-1bf3-58bc-bf77-1921df3eb266', 'D', 'Lobar collapse', false, 3),
  ('35923488-2353-510f-ba8b-c76a623ab355', '9c23ec57-1bf3-58bc-bf77-1921df3eb266', 'E', 'Cardiogenic pulmonary oedema', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('879a1c75-7b82-5be2-9d91-9c8e402e9eb2', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000031', 'sba', 'A 66 year old man presents with inability to pass urine for 12 hours and severe lower abdominal pain. He had a cold and took an over-the-counter decongestant. He has had nocturia and poor stream for 2 years. His bladder is palpable to the umbilicus. A catheter is inserted and drains 1,100 mL. His creatinine is 140 micromol/L (baseline 85). What is the MOST appropriate management?', 'Acute urinary retention is often triggered by drugs (decongestants, anticholinergics, opioids), constipation or infection on a background of BPH. Alpha-blockers improve the chance of successful TWOC. Monitor urine output and electrolytes (post-obstructive diuresis) if residual over 1 L or renal impairment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6a404607-5b2d-5a5c-bcfe-1a3ade2329e2', '879a1c75-7b82-5be2-9d91-9c8e402e9eb2', 'A', 'Immediate TURP', false, 0),
  ('c8048a9c-0649-5f4e-80bb-4ecedb70bc65', '879a1c75-7b82-5be2-9d91-9c8e402e9eb2', 'B', 'Start finasteride and remove catheter now', false, 1),
  ('0a4f809a-0cd2-528e-846b-3042c4934fd5', '879a1c75-7b82-5be2-9d91-9c8e402e9eb2', 'C', 'IV antibiotics only', false, 2),
  ('5b30ea58-4f47-5393-b6ac-c2af66c23a3e', '879a1c75-7b82-5be2-9d91-9c8e402e9eb2', 'D', 'Keep the catheter, start tamsulosin, and plan a trial without catheter after 2-3 days; monitor for post-obstructive diuresis', true, 3),
  ('5c387733-1c61-5d0b-8a7c-7adf5ecb0218', '879a1c75-7b82-5be2-9d91-9c8e402e9eb2', 'E', 'Remove the catheter immediately', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d9bcdd33-f603-5d12-9b2e-88460af3b19d', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000031', 'sba', 'A 78 year old man has been referred because his creatinine has risen to 290 micromol/L over 3 months. He has a palpable bladder and has been passing small amounts of urine frequently with dribbling. He has nocturnal enuresis. Ultrasound shows bilateral hydronephrosis and a thickened bladder wall with a residual of 1,500 mL. What is the SINGLE most likely diagnosis?', 'High-pressure chronic retention: painless, bedwetting, renal impairment and bilateral hydronephrosis. Catheterise and monitor for post-obstructive diuresis (may need IV fluids). Long-term: TURP or long-term catheter. Do not attempt TWOC without definitive treatment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a7dbda2c-20eb-510f-bed3-fa46230acce2', 'd9bcdd33-f603-5d12-9b2e-88460af3b19d', 'A', 'Bladder cancer', false, 0),
  ('2a1111d3-590c-5ab9-bef7-a6bd581ac891', 'd9bcdd33-f603-5d12-9b2e-88460af3b19d', 'B', 'Stress incontinence', false, 1),
  ('920972a9-e85f-5cab-ac9f-ab9f66706642', 'd9bcdd33-f603-5d12-9b2e-88460af3b19d', 'C', 'High-pressure chronic urinary retention', true, 2),
  ('10f8e05e-04ee-516a-a41b-150510c9f51b', 'd9bcdd33-f603-5d12-9b2e-88460af3b19d', 'D', 'Acute urinary retention', false, 3),
  ('5344ffc7-b5cb-53a4-aa41-4b3377f32e6c', 'd9bcdd33-f603-5d12-9b2e-88460af3b19d', 'E', 'Overactive bladder', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('27650507-d754-51f1-9648-e87aec211043', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000032', 'sba', 'A 74 year old woman presents with a painful, pale right foot that started suddenly 6 hours ago. She has had claudication in this leg for 3 years. On examination the foot is cold and white. There is reduced sensation over the toes but she can move them. Femoral pulse is present but popliteal and foot pulses are absent. Hand-held Doppler signals are absent in the foot arteries. She is in sinus rhythm. What is the SINGLE most likely cause and management?', 'Thrombosis in situ on existing atherosclerosis is more common in people with claudication and no embolic source. Imaging guides endovascular or surgical treatment. Embolism is more likely with AF and no previous claudication.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('81195f42-e332-5bd3-8688-7eb0a0a4a3b8', '27650507-d754-51f1-9648-e87aec211043', 'A', 'Cellulitis; antibiotics', false, 0),
  ('cf9bae6e-e64b-55f4-baf1-137f0da58928', '27650507-d754-51f1-9648-e87aec211043', 'B', 'Acute-on-chronic thrombosis; IV heparin and urgent vascular review with CT angiography for revascularisation', true, 1),
  ('a83c5a18-1ce9-5a23-ba20-866c1a1af908', '27650507-d754-51f1-9648-e87aec211043', 'C', 'Embolism from AF; immediate embolectomy without imaging', false, 2),
  ('aabd3d4d-cf0e-5a63-b9e6-bc7c559e87e0', '27650507-d754-51f1-9648-e87aec211043', 'D', 'DVT; anticoagulation only', false, 3),
  ('709d7132-cb17-58f3-94f6-4e229958f5e1', '27650507-d754-51f1-9648-e87aec211043', 'E', 'Chronic ischaemia; routine outpatient referral', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('33bc9f7d-22e6-5a10-b34a-0528d015a1ae', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000020', 'sba', 'A 22 year old man presents with a 3-day history of painful urination and a thick yellow urethral discharge. He had unprotected sex with a new partner 5 days ago. Microscopy of a urethral swab shows Gram-negative intracellular diplococci. What is the SINGLE most appropriate treatment?', 'BASHH: gonorrhoea is treated with ceftriaxone 1 g IM. Ciprofloxacin only if known sensitive. Test of cure (rising antimicrobial resistance). Screen for chlamydia, HIV and syphilis. Partner notification.', null, true, true, jsonb_build_object('source', 'plab1-xlsx-v7', 'guidelines_text', 'BASHH')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cb614d78-7c8e-5cdf-9fa5-a89058184133', '33bc9f7d-22e6-5a10-b34a-0528d015a1ae', 'A', 'Oral ciprofloxacin in all', false, 0),
  ('bcd36ce0-e736-5451-80af-874c42535ba6', '33bc9f7d-22e6-5a10-b34a-0528d015a1ae', 'B', 'Ceftriaxone 1 g IM single dose, with test of cure and partner notification', true, 1),
  ('38f23200-d6bf-56eb-a259-d54224283c75', '33bc9f7d-22e6-5a10-b34a-0528d015a1ae', 'C', 'Doxycycline alone', false, 2),
  ('d43b953e-65e4-5fdc-aae0-5471640f189a', '33bc9f7d-22e6-5a10-b34a-0528d015a1ae', 'D', 'Benzathine penicillin', false, 3),
  ('80e48a6e-91bb-56d5-9ba4-72d15a4912ad', '33bc9f7d-22e6-5a10-b34a-0528d015a1ae', 'E', 'Azithromycin alone', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d63c14b6-b78f-51f7-806a-82860641b698', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000020', 'sba', 'A 19 year old woman presents with painful vulval ulcers for 3 days, difficulty passing urine, fever and muscle aches. She had unprotected sex with a new partner 1 week ago. On examination there are multiple small, shallow, painful ulcers on the labia and tender inguinal lymphadenopathy. What is the SINGLE most appropriate management?', 'Primary genital herpes: painful ulcers, systemic symptoms, dysuria and urinary retention. Swab for HSV PCR. Start antivirals within 5 days. Lidocaine gel and passing urine in a warm bath help. Suppressive therapy for frequent recurrences. Primary infection in late pregnancy increases neonatal herpes risk (consider caesarean).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f0cf3891-b214-533f-ad92-b537cbde6f08', 'd63c14b6-b78f-51f7-806a-82860641b698', 'A', 'Clotrimazole cream', false, 0),
  ('cec13765-9efb-56f6-8fda-adcc419be8d5', 'd63c14b6-b78f-51f7-806a-82860641b698', 'B', 'Metronidazole', false, 1),
  ('f03ae137-2343-5bc9-8a7f-484fe5e0c502', 'd63c14b6-b78f-51f7-806a-82860641b698', 'C', 'Azithromycin', false, 2),
  ('0276fba1-f8ab-5ff3-94bd-9d6dcf35cf24', 'd63c14b6-b78f-51f7-806a-82860641b698', 'D', 'IM benzathine penicillin', false, 3),
  ('7470726d-e0a7-5879-907d-2cadd2172123', 'd63c14b6-b78f-51f7-806a-82860641b698', 'E', 'Oral aciclovir for 5 days, analgesia, saline bathing and STI screen', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c4ae4973-b9fa-5101-a574-66e1f2862663', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 58 year old woman with known breast cancer metastatic to bone presents with new thoracic back pain worse at night and when lying flat. She has no leg weakness, sensory level or sphincter disturbance. Plain X-ray shows no fracture. What is the SINGLE most appropriate next step?', 'NICE NG234: in people with cancer, spinal pain suggestive of metastases needs MRI within 1 week; neurological symptoms or signs suggestive of MSCC need MRI within 24 hours. Give dexamethasone if MSCC is suspected.', null, true, true, jsonb_build_object('source', 'plab1-xlsx-v7', 'guidelines_text', 'NICE NG234')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d1eeda26-456a-58e4-a845-74a799b105e2', 'c4ae4973-b9fa-5101-a574-66e1f2862663', 'A', 'Whole-spine MRI within 1 week (or within 24 hours if neurological symptoms develop), with analgesia and advice to report any new neurological symptoms', true, 0),
  ('b46f7d66-2e62-50cc-a564-ff34c74f573d', 'c4ae4973-b9fa-5101-a574-66e1f2862663', 'B', 'Reassure and review in 3 months', false, 1),
  ('f0dc55da-0ffb-5422-819f-5b79e2d4cf4b', 'c4ae4973-b9fa-5101-a574-66e1f2862663', 'C', 'Bone scan only', false, 2),
  ('cad92af0-3f5d-59a8-9ea5-3d8029ecefb4', 'c4ae4973-b9fa-5101-a574-66e1f2862663', 'D', 'Bed rest', false, 3),
  ('3cbe452c-ffb5-5fb8-ad21-2bc5d45fb228', 'c4ae4973-b9fa-5101-a574-66e1f2862663', 'E', 'Physiotherapy referral', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('08aad476-4e45-54e0-ae65-f68c52fc724a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 66 year old man presents with a 2-month history of progressive difficulty swallowing solids, now also liquids, and weight loss of 7 kg. He has a long history of heartburn. He has iron deficiency anaemia. There is no palpable mass. What is the SINGLE most appropriate next step?', 'NICE NG12: dysphagia at any age needs urgent endoscopy. Progressive dysphagia with weight loss and GORD history suggests oesophageal adenocarcinoma (Barrett''s). Squamous cell carcinoma is linked with smoking and alcohol.', null, true, true, jsonb_build_object('source', 'plab1-xlsx-v7', 'guidelines_text', 'NICE NG12')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('f50cc150-a155-5459-a14c-d85d5bb2415c', '08aad476-4e45-54e0-ae65-f68c52fc724a', 'A', 'Trial of PPI for 8 weeks', false, 0),
  ('c5235f04-7c4e-54dd-9516-19d6f0f74e8c', '08aad476-4e45-54e0-ae65-f68c52fc724a', 'B', 'Barium swallow', false, 1),
  ('1829a2de-785e-5ef3-a939-dbfc456e3966', '08aad476-4e45-54e0-ae65-f68c52fc724a', 'C', 'CT chest', false, 2),
  ('c49fe63a-072c-5bc7-8e00-bb4f2293d6c7', '08aad476-4e45-54e0-ae65-f68c52fc724a', 'D', 'Manometry', false, 3),
  ('6ae9735a-33e1-526b-b0bc-16ef78c74f97', '08aad476-4e45-54e0-ae65-f68c52fc724a', 'E', 'Urgent direct-access upper GI endoscopy (two-week-wait)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('161c7c9e-380a-5131-a397-d8ee3d2ae726', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 72 year old man has had a cough, weight loss and haemoptysis for 2 months. He smokes 40 pack-years. Blood tests show calcium 3.1 mmol/L, PTH low. CXR shows a large central mass in the right hilum with cavitation. What is the SINGLE most likely tumour type?', 'Squamous cell lung cancer is central, may cavitate, and causes hypercalcaemia through PTHrP. Small cell cancer causes SIADH, ectopic ACTH and Lambert-Eaton syndrome. Adenocarcinoma is peripheral and the commonest type in non-smokers.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('a3d97169-cf53-52c1-8952-0de175b48b8f', '161c7c9e-380a-5131-a397-d8ee3d2ae726', 'A', 'Large cell carcinoma', false, 0),
  ('8da9803f-9ba8-56d1-8a88-7e2f02cc6025', '161c7c9e-380a-5131-a397-d8ee3d2ae726', 'B', 'Mesothelioma', false, 1),
  ('0ee6f926-c147-5f87-bbc2-a616ca387333', '161c7c9e-380a-5131-a397-d8ee3d2ae726', 'C', 'Small cell lung cancer', false, 2),
  ('8b9c8a81-8b68-538e-ad3c-f9363f7b4711', '161c7c9e-380a-5131-a397-d8ee3d2ae726', 'D', 'Squamous cell carcinoma of the lung (PTHrP secretion)', true, 3),
  ('c9363fff-dde4-511f-922d-95ba3c05652c', '161c7c9e-380a-5131-a397-d8ee3d2ae726', 'E', 'Adenocarcinoma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b3db53d0-759f-5a41-849d-dc9cdb568626', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000025', 'sba', 'A 25 year old man is brought to the emergency department after a fall from a height of 4 metres. He has neck pain. GCS is 15. He has tenderness over the cervical spine and tingling in both arms. He is on a scoop stretcher with his neck immobilised. What is the SINGLE most appropriate imaging?', 'NICE NG41: in adults with high-risk factors (dangerous mechanism, age 65 or more, paraesthesia in the arms) or neurological signs, CT cervical spine is first-line. MRI if neurological signs or suspected ligament or cord injury.', null, true, true, jsonb_build_object('source', 'plab1-xlsx-v7', 'guidelines_text', 'NICE NG41')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('3dfcc32c-d3b3-5f22-9fbc-fa285e99f5b9', 'b3db53d0-759f-5a41-849d-dc9cdb568626', 'A', 'MRI only after 24 hours', false, 0),
  ('130ec04a-be4a-5403-a0e8-122c87e7f8ed', 'b3db53d0-759f-5a41-849d-dc9cdb568626', 'B', 'CT cervical spine within 1 hour', true, 1),
  ('3f1502fc-f30d-5ce9-84d9-634308091bc4', 'b3db53d0-759f-5a41-849d-dc9cdb568626', 'C', 'Clinical clearance without imaging', false, 2),
  ('7e049856-5992-5e48-b3b4-1e0d51d805e9', 'b3db53d0-759f-5a41-849d-dc9cdb568626', 'D', 'Plain X-ray of the cervical spine', false, 3),
  ('710a62e2-472c-50a2-9c80-6ede2dc709d6', 'b3db53d0-759f-5a41-849d-dc9cdb568626', 'E', 'Ultrasound of the neck', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5a603229-b1d2-5bba-87af-aa2852967429', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000025', 'sba', 'A 30 year old woman fell from her horse and hit her head. She lost consciousness for 2 minutes and vomited twice. She is now GCS 15 with a headache. She takes no medications. What is the SINGLE most appropriate imaging?', 'NICE NG232: CT head within 1 hour for GCS under 13 initially or under 15 at 2 hours, suspected open or depressed skull fracture, signs of basal skull fracture, post-traumatic seizure, focal deficit, or more than one episode of vomiting. CT within 8 hours if on anticoagulants (any loss of consciousness or amnesia).', null, true, true, jsonb_build_object('source', 'plab1-xlsx-v7', 'guidelines_text', 'NICE NG232', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/Epidural_hematoma.png')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e377de61-d39e-59fd-bd0c-028765bf2037', '5a603229-b1d2-5bba-87af-aa2852967429', 'A', 'Skull X-ray', false, 0),
  ('dcf4ee0d-d073-5082-b636-9b6d1b2d67da', '5a603229-b1d2-5bba-87af-aa2852967429', 'B', 'No imaging needed', false, 1),
  ('99a4dbdb-a225-5312-ae25-4682ebd32a83', '5a603229-b1d2-5bba-87af-aa2852967429', 'C', 'MRI head the next week', false, 2),
  ('34ccad44-aaa3-5f15-90f7-9a19a78d5dbb', '5a603229-b1d2-5bba-87af-aa2852967429', 'D', 'CT head within 1 hour (more than one episode of vomiting)', true, 3),
  ('c9fd8104-cc28-5162-8c32-c4e21ae32b80', '5a603229-b1d2-5bba-87af-aa2852967429', 'E', 'CT head within 8 hours', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8d7bc506-ea7a-564f-8516-56811aedab46', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000022', 'sba', 'A 46 year old woman is referred with a 3 cm hard lump in her left breast for 1 month. On examination it is irregular and tethered to the skin with a palpable mobile axillary lymph node. Mammogram shows a spiculated mass with microcalcification. Core biopsy shows invasive ductal carcinoma, grade 3, ER-positive, HER2-negative. Staging CT shows no distant metastases. Ultrasound-guided biopsy of the node is positive. What is the MOST appropriate next step?', 'Breast cancer is managed by an MDT. Node-positive disease needs axillary treatment (clearance or radiotherapy). ER-positive tumours receive endocrine therapy (tamoxifen premenopausal, aromatase inhibitor postmenopausal). Chemotherapy is often given for high grade or node-positive disease; genomic tests guide some decisions.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('05d5946b-3dc3-5f0e-aea7-a097a7214a0e', '8d7bc506-ea7a-564f-8516-56811aedab46', 'A', 'Radiotherapy only', false, 0),
  ('30656491-3214-555d-a192-a0378a9f1683', '8d7bc506-ea7a-564f-8516-56811aedab46', 'B', 'Chemotherapy only', false, 1),
  ('ac1c3d36-f8ef-52b4-9bc9-5340586c6864', '8d7bc506-ea7a-564f-8516-56811aedab46', 'C', 'Endocrine therapy alone with no surgery', false, 2),
  ('0f601869-92f4-5331-bcbd-23cdcb812201', '8d7bc506-ea7a-564f-8516-56811aedab46', 'D', 'Review in 6 months', false, 3),
  ('79ca7047-bc26-58d8-aa83-7659c7207f69', '8d7bc506-ea7a-564f-8516-56811aedab46', 'E', 'Multidisciplinary team discussion to plan surgery (breast-conserving or mastectomy) with axillary treatment, adjuvant therapy and endocrine therapy', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('004ba823-50fe-516c-b752-102acdde5032', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000017', 'sba', 'A 72 year old woman with metastatic pancreatic cancer is being cared for at home. Her pain has been controlled on oral morphine modified-release 30 mg twice daily with morphine oral solution 10 mg for breakthrough. Over the past 2 days she has needed 5 breakthrough doses a day. She is alert, and her renal function is normal. What is the SINGLE most appropriate change?', 'Titrate regular opioids by adding the total breakthrough doses used over 24 hours (or increase by 30-50%). Breakthrough is about one-sixth of the 24-hour dose. Prescribe a laxative and antiemetic. Coeliac plexus block may help pancreatic cancer pain.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('3d7c3b69-c0cf-55eb-ab8f-1c39cdb24b7a', '004ba823-50fe-516c-b752-102acdde5032', 'A', 'Stop morphine and start paracetamol only', false, 0),
  ('90a6bdd8-fb2b-5ae1-859d-37b53f8f9faa', '004ba823-50fe-516c-b752-102acdde5032', 'B', 'Add tramadol', false, 1),
  ('cabe5d42-1f69-501b-b5a5-9385328fcf9a', '004ba823-50fe-516c-b752-102acdde5032', 'C', 'Switch to codeine', false, 2),
  ('f04d66b7-6381-54ce-83b8-6c0ae47284c8', '004ba823-50fe-516c-b752-102acdde5032', 'D', 'Increase modified-release morphine to 55-60 mg twice daily (adding the breakthrough total), with breakthrough dose increased to one-sixth of the new 24-hour total', true, 3),
  ('23b3c70e-3aab-5d01-b651-e292676e33bf', '004ba823-50fe-516c-b752-102acdde5032', 'E', 'Keep the same dose', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5551baf5-4ac9-5bb7-bd1d-ea730ccc5813', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000017', 'sba', 'A 68 year old man with motor neurone disease is in a hospice. He is very breathless and anxious. He has capacity and has an advance decision refusing ventilation. He asks to have his NIV removed as it is now distressing him and he understands he will probably die. What is the SINGLE most appropriate action?', 'A patient with capacity can refuse life-sustaining treatment, including NIV. Withdrawing treatment at the patient''s request is not assisted dying. Plan carefully with anticipatory medications to manage breathlessness and distress (Association for Palliative Medicine guidance).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ff2e2567-1c87-58c0-8fa2-61ebd5626ef7', '5551baf5-4ac9-5bb7-bd1d-ea730ccc5813', 'A', 'Ask a court for permission', false, 0),
  ('c70aac1d-8d18-5cbc-b435-712083534a86', '5551baf5-4ac9-5bb7-bd1d-ea730ccc5813', 'B', 'Transfer to ICU for intubation', false, 1),
  ('8d707fd2-0d71-586d-aae0-d8bb096d7b45', '5551baf5-4ac9-5bb7-bd1d-ea730ccc5813', 'C', 'Respect his decision, plan NIV withdrawal with symptom control (opioids and benzodiazepines) and support for him and his family', true, 2),
  ('f5715fc6-c876-5724-8741-5df6828c0de5', '5551baf5-4ac9-5bb7-bd1d-ea730ccc5813', 'D', 'Refuse to remove NIV', false, 3),
  ('41fcde13-308d-5f26-bf5c-87cb4bb7e10d', '5551baf5-4ac9-5bb7-bd1d-ea730ccc5813', 'E', 'Remove NIV without symptom control', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ce27ad35-a4c1-58e2-a224-e3f1bc09633e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000028', 'sba', 'An FY1 doctor on a night shift is bleeped by three different wards at the same time: a patient with chest pain and new ST changes, a request to rewrite a drug chart, and a patient with a temperature of 37.8 °C who is otherwise well with normal observations. The doctor has just started a cannula on another patient. What is the MOST appropriate action?', 'Prioritisation uses clinical urgency (ABCDE, NEWS2). Communicate expected arrival times, escalate to the registrar and use the hospital at night team. Tasks such as rewriting charts can wait or be delegated.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('fbe55aa2-571e-5cfa-a007-b979d65dc6db', 'ce27ad35-a4c1-58e2-a224-e3f1bc09633e', 'A', 'Prioritise the chest pain patient immediately, ask for senior help, and delegate or defer the less urgent tasks with clear communication', true, 0),
  ('df28c461-53fd-5738-acd0-0c11965e519b', 'ce27ad35-a4c1-58e2-a224-e3f1bc09633e', 'B', 'Ask a nurse to treat the chest pain', false, 1),
  ('1d24ede1-bc17-5d7f-bdde-7b61d9ab383f', 'ce27ad35-a4c1-58e2-a224-e3f1bc09633e', 'C', 'See the patients in order of bleep', false, 2),
  ('c26e14c5-c478-594e-8e21-2e17afea4bd5', 'ce27ad35-a4c1-58e2-a224-e3f1bc09633e', 'D', 'Rewrite the drug chart first as it is quick', false, 3),
  ('ac278c47-8d3d-5f1e-b77c-e6a09c2a1ca1', 'ce27ad35-a4c1-58e2-a224-e3f1bc09633e', 'E', 'Ignore all bleeps until the cannula is finished', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8dec60b6-dbe5-54ee-8d42-c38539aca5f7', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000021', 'sba', 'A local public health team notices an increase in cases of measles in a city. Vaccine uptake of the second MMR dose is 82%. What is the MOST important public health action?', 'Herd immunity for measles needs about 95% coverage with 2 doses. Measles is notifiable. Contacts who are susceptible can receive MMR within 72 hours or immunoglobulin within 6 days (pregnant, immunosuppressed, infants). Exclude cases for 4 days after rash onset.', null, true, true, jsonb_build_object('source', 'plab1-xlsx-v7')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('ce1b05c1-a260-5944-b7db-9755db78dd18', '8dec60b6-dbe5-54ee-8d42-c38539aca5f7', 'A', 'Test all children for measles antibodies', false, 0),
  ('46d59ace-fff3-50a6-be9c-729a9ec67319', '8dec60b6-dbe5-54ee-8d42-c38539aca5f7', 'B', 'Catch-up MMR vaccination campaign targeting under-vaccinated groups, with contact tracing and exclusion of cases', true, 1),
  ('b2a5afb2-0d17-5d32-af16-4921ff25f462', '8dec60b6-dbe5-54ee-8d42-c38539aca5f7', 'C', 'Close all schools for a month', false, 2),
  ('1f5e3cde-9574-5cfc-bb13-f1135b5c7349', '8dec60b6-dbe5-54ee-8d42-c38539aca5f7', 'D', 'Wait for natural immunity', false, 3),
  ('3de99260-844b-5fd9-b307-81908a14a881', '8dec60b6-dbe5-54ee-8d42-c38539aca5f7', 'E', 'Give antibiotics to contacts', false, 4);
